const GD_SOURCES = {"BattleEngine.gd": "class_name BattleEngine\nextends Node\n## 核心对战规则与词条结算引擎 (BattleEngine)\n## 完整实现《影之诗》×《邪恶冥刻》5列战道、三维费用（能量/献祭/骨头）、26+词条与38张卡牌精确效果结算\n\n## 战场状态变更信号（通知 UI 刷新与播放 Tween 动画）\nsignal state_updated()\nsignal battle_log_added(msg: String)\nsignal floating_text_requested(side: int, lane: int, text: String, color: Color)\nsignal attack_anim_requested(attacker_side: int, attacker_lane: int, target_side: int, target_lane: int)\nsignal guard_move_requested(defender_side: int, from_lane: int, to_lane: int)\nsignal game_over_triggered(winner_side: int, reason: String)\n\n## 阵营常量定义\nconst PLAYER: int = 0\nconst ENEMY: int = 1\nconst LANES: int = 5\n\n## 双方主战者状态字典（索引 0 = 玩家，1 = 敌方 AI）\nvar leaders: Array[Dictionary] = [{}, {}]\n## 双方 5 列战道随从数组：board[side][lane] -> CardInstance 或 null\nvar board: Array = [[null, null, null, null, null], [null, null, null, null, null]]\n## 当前回合号（从 1 开始）\nvar turn_number: int = 1\n## 当前行动阵营（0 = 玩家，1 = 敌方）\nvar active_side: int = PLAYER\n## 对战是否已结束\nvar is_game_over: bool = false\nvar _enter_seq: int = 0\n\n## 初始化新对战\nfunc start_battle(player_deck_ids: Array[String], enemy_deck_ids: Array[String]) -> void:\n\tis_game_over = false\n\tturn_number = 1\n\tactive_side = PLAYER\n\tboard = [[null, null, null, null, null], [null, null, null, null, null]]\n\tleaders[PLAYER] = _create_leader_state(PLAYER, player_deck_ids)\n\tleaders[ENEMY] = _create_leader_state(ENEMY, enemy_deck_ids)\n\t_prepare_opening_hand(PLAYER)\n\t_prepare_opening_hand(ENEMY)\n\t_log(\"⚔️ 对战开始！双方主战者初始生命值 %d 点。\" % int(CardDatabase.rules.get(\"hp\", 20)))\n\nfunc _create_leader_state(side: int, deck_ids: Array[String]) -> Dictionary:\n\tvar deck_instances: Array[CardInstance] = []\n\tfor cid in deck_ids:\n\t\tvar inst: CardInstance = CardDatabase.create_instance(cid, side)\n\t\tif inst != null:\n\t\t\tdeck_instances.append(inst)\n\tdeck_instances.shuffle()\n\treturn {\n\t\t\"hp\": int(CardDatabase.rules.get(\"hp\", 20)),\n\t\t\"max_hp\": int(CardDatabase.rules.get(\"hp\", 20)),\n\t\t\"energy\": int(CardDatabase.rules.get(\"energyStart\", 1)),\n\t\t\"max_energy\": int(CardDatabase.rules.get(\"energyStart\", 1)),\n\t\t\"bones\": 0,\n\t\t\"deck\": deck_instances,\n\t\t\"hand\": [] as Array[CardInstance],\n\t\t\"graveyard\": [] as Array[CardData], # 墓地存储被破坏的随从静态数据\n\t\t\"destroyed_last_words_count\": 0,    # 本局被破坏的具有谢幕曲的随从计数\n\t\t\"cards_played_this_turn\": 0,        # 本回合已使用卡牌张数（用于「连击」词条）\n\t\t\"next_mech_discount\": 0,            # 下一张机械随从能量减免（如「铜壳瓢虫」）\n\t\t\"delayed_mech_draws\": 0             # 下回合开始时额外抽取机械随从次数（如「飞轮信使」）\n\t}\n\n## 处理起手 4 张抽牌，确保「使命必达小子」(cmwbz163tt1ma) 必定出现在未换牌前的起手手牌中\nfunc _prepare_opening_hand(side: int) -> void:\n\tvar st: Dictionary = leaders[side]\n\tvar deck: Array = st[\"deck\"]\n\tvar hand: Array = st[\"hand\"]\n\tvar opening_count: int = int(CardDatabase.rules.get(\"openingHand\", 4))\n\t# 检查牌库中是否有「使命必达小子」，若有则先移到牌库顶确保首抽必得\n\tfor i in range(deck.size()):\n\t\tvar inst: CardInstance = deck[i]\n\t\tif inst.data.id == \"cmwbz163tt1ma\" or inst.data.text.find(\"必定会出现在未洗牌前的起手手牌\") != -1:\n\t\t\tdeck.remove_at(i)\n\t\t\tdeck.push_front(inst)\n\t\t\tbreak\n\tfor i in range(opening_count):\n\t\tdraw_card(side, false)\n\n## 执行起手调度换牌（玩家可勾选任意张卡牌洗回牌库并重抽等量卡牌）\nfunc perform_mulligan(side: int, replace_indices: Array[int]) -> void:\n\tif replace_indices.is_empty():\n\t\treturn\n\tvar st: Dictionary = leaders[side]\n\tvar hand: Array = st[\"hand\"]\n\tvar deck: Array = st[\"deck\"]\n\treplace_indices.sort()\n\treplace_indices.reverse()\n\tvar returned: Array[CardInstance] = []\n\tfor idx in replace_indices:\n\t\tif idx >= 0 and idx < hand.size():\n\t\t\treturned.append(hand[idx])\n\t\t\thand.remove_at(idx)\n\tfor c in returned:\n\t\tdeck.append(c)\n\tdeck.shuffle()\n\tfor i in range(returned.size()):\n\t\tdraw_card(side, false)\n\t_log(\"🔄 玩家完成了起手换牌（替换了 %d 张手牌）。\" % returned.size())\n\tstate_updated.emit()\n\n## 开始指定阵营的回合\nfunc begin_turn(side: int) -> void:\n\tif is_game_over:\n\t\treturn\n\tactive_side = side\n\tvar st: Dictionary = leaders[side]\n\tst[\"cards_played_this_turn\"] = 0\n\t# 第 1 回合双方均为 1 点能量；从第 2 回合开始每回合能量上限+1（最高 10）并回满\n\tvar e_max: int = int(CardDatabase.rules.get(\"energyMax\", 10))\n\tif turn_number > 1:\n\t\tst[\"max_energy\"] = min(e_max, int(st[\"max_energy\"]) + 1)\n\tst[\"energy\"] = st[\"max_energy\"]\n\n\t# 重置场上随从本回合「启动」状态与倒计时\n\tfor lane in range(LANES):\n\t\tvar m: CardInstance = board[side][lane]\n\t\tif m != null:\n\t\t\tm.activated_this_turn = false\n\n\t_log(\"—— 【%s的第 %d 回合】 能量 %d/%d | 骨头 %d ——\" % [\n\t\t\"我方\" if side == PLAYER else \"敌方\",\n\t\tturn_number,\n\t\tint(st[\"energy\"]),\n\t\tint(st[\"max_energy\"]),\n\t\tint(st[\"bones\"])\n\t])\n\n\t# 回合开始常规抽 1 张牌（后手第一回合额外多抽 1 张牌）\n\tdraw_card(side)\n\tif side == ENEMY and turn_number == 1:\n\t\tdraw_card(side)\n\t\t_log(\"✨ 后手第一回合额外抽取 1 张卡牌。\")\n\n\t# 结算「飞轮信使」等延迟回合开始检索机械随从效果\n\twhile int(st[\"delayed_mech_draws\"]) > 0:\n\t\tst[\"delayed_mech_draws\"] = int(st[\"delayed_mech_draws\"]) - 1\n\t\tdraw_specific_race(side, \"机械\")\n\n\t# 结算场上从左到右（敌方从右到左）的【回合开始时】效果\n\tvar order: Array[int] = _get_lane_order(side)\n\tfor lane in order:\n\t\tvar m: CardInstance = board[side][lane]\n\t\tif m != null:\n\t\t\t_trigger_turn_start_effects(side, lane, m)\n\n\tstate_updated.emit()\n\n## 抽取 1 张卡牌\nfunc draw_card(side: int, emit_ui: bool = true) -> CardInstance:\n\tvar st: Dictionary = leaders[side]\n\tvar deck: Array = st[\"deck\"]\n\tvar hand: Array = st[\"hand\"]\n\tvar hand_limit: int = int(CardDatabase.rules.get(\"handLimit\", 8))\n\tif deck.is_empty():\n\t\treturn null\n\tvar card: CardInstance = deck.pop_front()\n\tif hand.size() >= hand_limit:\n\t\t_log(\"⚠️ %s手牌已满（%d张），抽到的【%s】爆牌消失！\" % [\"我方\" if side == PLAYER else \"敌方\", hand_limit, card.data.name])\n\t\treturn null\n\thand.append(card)\n\tAudioManager.play_sfx(\"draw\")\n\tif emit_ui:\n\t\tstate_updated.emit()\n\treturn card\n\n## 从牌库检索指定种族的随从加入手牌（如「飞轮信使」谢幕曲）\nfunc draw_specific_race(side: int, target_race: String) -> CardInstance:\n\tvar st: Dictionary = leaders[side]\n\tvar deck: Array = st[\"deck\"]\n\tfor i in range(deck.size()):\n\t\tvar c: CardInstance = deck[i]\n\t\tif c.data.type == \"minion\" and c.data.race == target_race:\n\t\t\tdeck.remove_at(i)\n\t\t\tvar hand: Array = st[\"hand\"]\n\t\t\tif hand.size() < int(CardDatabase.rules.get(\"handLimit\", 8)):\n\t\t\t\thand.append(c)\n\t\t\t\t_log(\"🔍 %s从牌库检索了机械随从【%s】加入手牌。\" % [\"我方\" if side == PLAYER else \"敌方\", c.data.name])\n\t\t\tstate_updated.emit()\n\t\t\treturn c\n\treturn null\n\n## 将指定卡牌名称的衍生物或卡牌加入手牌（如「电子羊」「骨龙」）\nfunc add_card_to_hand(side: int, card_name_or_id: String, count: int = 1) -> void:\n\tvar st: Dictionary = leaders[side]\n\tvar hand: Array = st[\"hand\"]\n\tvar hand_limit: int = int(CardDatabase.rules.get(\"handLimit\", 8))\n\tfor i in range(count):\n\t\tif hand.size() >= hand_limit:\n\t\t\t_log(\"⚠️ %s手牌已达上限 %d 张，无法继续加入【%s】。\" % [\"我方\" if side == PLAYER else \"敌方\", hand_limit, card_name_or_id])\n\t\t\tbreak\n\t\tvar inst: CardInstance = CardDatabase.create_instance(card_name_or_id, side)\n\t\tif inst != null:\n\t\t\thand.append(inst)\n\tstate_updated.emit()\n\n## 检查某张手牌当前是否满足费用与献祭条件可打出\nfunc can_play_card(side: int, card: CardInstance) -> Dictionary:\n\tvar st: Dictionary = leaders[side]\n\tvar need_energy: int = card.get_effective_energy(int(st[\"next_mech_discount\"]))\n\tvar need_bones: int = card.data.bones\n\tvar need_sac: int = card.data.sacrifice\n\tvar sac_cond: String = card.data.sacrifice_cond\n\n\tif int(st[\"energy\"]) < need_energy:\n\t\treturn {\"ok\": false, \"reason\": \"能量不足（需要 %d 点能量）\" % need_energy}\n\tif int(st[\"bones\"]) < need_bones:\n\t\treturn {\"ok\": false, \"reason\": \"骨头不足（需要 %d 根骨头）\" % need_bones}\n\n\t# 检查献祭条件\n\tvar valid_sac_lanes: Array[int] = get_valid_sacrifice_lanes(side, sac_cond)\n\tif valid_sac_lanes.size() < need_sac:\n\t\tvar cond_str: String = (\"「%s」\" % sac_cond) if sac_cond != \"\" else \"\"\n\t\treturn {\"ok\": false, \"reason\": \"献祭祭品不足（需要献祭 %d 个%s友方随从）\" % [need_sac, cond_str]}\n\n\t# 若是随从且无需献祭，则场上必须至少有 1 个空位（若需要献祭，根据规则“位置满时依然可以使用，献祭后会腾出位置”）\n\tif card.data.type == \"minion\" and need_sac == 0:\n\t\tvar has_empty: bool = false\n\t\tfor l in range(LANES):\n\t\t\tif board[side][l] == null:\n\t\t\t\thas_empty = true\n\t\t\t\tbreak\n\t\tif not has_empty:\n\t\t\treturn {\"ok\": false, \"reason\": \"战场上没有空余格子\"}\n\n\treturn {\"ok\": true, \"reason\": \"\"}\n\n## 获取场上满足指定献祭种族条件的友方随从所在列索引列表\nfunc get_valid_sacrifice_lanes(side: int, sac_cond: String) -> Array[int]:\n\tvar lanes: Array[int] = []\n\tfor l in range(LANES):\n\t\tvar m: CardInstance = board[side][l]\n\t\tif m != null:\n\t\t\tif sac_cond == \"\" or m.data.race == sac_cond:\n\t\t\t\tlanes.append(l)\n\treturn lanes\n\n## 判断某张卡牌在当前能量下是否会触发【爆能强化】\nfunc will_trigger_enhance(side: int, card: CardInstance) -> int:\n\tvar st: Dictionary = leaders[side]\n\tfor kw in card.data.keywords:\n\t\tif str(kw.get(\"k\", \"\")) == \"爆能强化\":\n\t\t\tvar enh_val: int = int(kw.get(\"v\", 0))\n\t\t\tif int(st[\"energy\"]) >= enh_val:\n\t\t\t\treturn enh_val\n\treturn 0\n\n## 获取卡牌的【抉择】选项列表（若无抉择则返回空数组）\nfunc get_card_choices(card: CardInstance) -> Array:\n\tfor kw in card.data.keywords:\n\t\tvar choice_dict: Dictionary = kw.get(\"choice\", {})\n\t\tif bool(choice_dict.get(\"on\", false)):\n\t\t\treturn choice_dict.get(\"opts\", [])\n\treturn []\n\n## 判断卡牌从手牌打出时是否需要指定敌方/友方目标，或是选择手牌\nfunc get_card_target_requirement(card: CardInstance, is_enhanced: bool = false) -> String:\n\t# 返回值：\"\"（无需目标）、\"enemy_minion\"（任意敌方随从）、\"enemy_minion_hp3\"（生命值3以下敌方随从）、\"friendly_minion\"（友方随从）、\"hand_card\"（手牌）\n\tmatch card.data.id:\n\t\t\"cmwbxdn7tcvde\": # 滑板跃迁手：选择一张手牌洗入牌库并抽1张\n\t\t\treturn \"hand_card\"\n\t\t\"cmwc0t61ade7b\": # 血偿者：选择对手战场上1个随从造成3点伤害\n\t\t\treturn \"enemy_minion\"\n\t\t\"cmwcah8st1lar\": # 神圣法典：选择1个生命值3以下敌方随从使其消失\n\t\t\treturn \"enemy_minion_hp3\"\n\t\t\"cmwcalky6itcu\": # 烟消云散：选择1个敌方随从使其和同名敌方随从消失\n\t\t\treturn \"enemy_minion\"\n\t\t\"cmwcaqbzuvvcx\": # 转生苹果：选择1个友方随从赋予同名复活谢幕曲\n\t\t\treturn \"friendly_minion\"\n\t\t\"cmwcb1izpxl7e\": # 连锁飞刃：选择1个敌方随从造成3点伤害（连击3造成5点）\n\t\t\treturn \"enemy_minion\"\n\t\t\"cmwcba1blx523\": # 炽炎之术：爆能强化5时改为全体3伤无需指定；否则选择1个敌方随从\n\t\t\treturn \"\" if is_enhanced else \"enemy_minion\"\n\treturn \"\"\n\n## 获取法术或入场曲的合法目标列索引列表（自动过滤具有【灵气】或【潜行】的敌方随从）\nfunc get_valid_target_lanes(caster_side: int, req_type: String, is_spell: bool) -> Array[int]:\n\tvar res: Array[int] = []\n\tvar opp_side: int = 1 - caster_side\n\tif req_type == \"enemy_minion\" or req_type == \"enemy_minion_hp3\":\n\t\tfor l in range(LANES):\n\t\t\tvar m: CardInstance = board[opp_side][l]\n\t\t\tif m != null:\n\t\t\t\t# 潜行随从无法被敌方选中；法术无法指定具有【灵气】的随从\n\t\t\t\tif m.has_kw(\"潜行\"):\n\t\t\t\t\tcontinue\n\t\t\t\tif is_spell and m.has_kw(\"灵气\"):\n\t\t\t\t\tcontinue\n\t\t\t\tif req_type == \"enemy_minion_hp3\" and m.current_hp > 3:\n\t\t\t\t\tcontinue\n\t\t\t\tres.append(l)\n\telif req_type == \"friendly_minion\":\n\t\tfor l in range(LANES):\n\t\t\tif board[caster_side][l] != null:\n\t\t\t\tres.append(l)\n\treturn res\n\n## 核心出牌执行函数：完成献祭破坏、费用扣除、随从入场、入场曲/法术效果结算与立即攻击\nfunc play_card_from_hand(\n\tside: int,\n\tcard: CardInstance,\n\ttarget_lane: int = 0,\n\tsacrifice_lanes: Array[int] = [],\n\teffect_target_lane: int = -1,\n\tchoice_index: int = 0,\n\thand_target_uid: int = -1\n) -> bool:\n\tvar check: Dictionary = can_play_card(side, card)\n\tif not bool(check.get(\"ok\", false)):\n\t\treturn false\n\n\tvar st: Dictionary = leaders[side]\n\tvar hand: Array = st[\"hand\"]\n\tvar need_energy: int = card.get_effective_energy(int(st[\"next_mech_discount\"]))\n\tvar enh_cost: int = will_trigger_enhance(side, card)\n\tvar is_enhanced: bool = (enh_cost > 0 and int(st[\"energy\"]) >= enh_cost)\n\tif is_enhanced:\n\t\tneed_energy = enh_cost\n\n\t# 1. 先执行献祭（破坏指定的友方随从，腾出格子并触发其谢幕曲与骨头+1）\n\tif card.data.sacrifice > 0:\n\t\tAudioManager.play_sfx(\"sacrifice\")\n\t\tfor sac_l in sacrifice_lanes:\n\t\t\tvar sac_m: CardInstance = board[side][sac_l]\n\t\t\tif sac_m != null:\n\t\t\t\t_log(\"🩸 %s献祭了随从【%s】！\" % [\"我方\" if side == PLAYER else \"敌方\", sac_m.data.name])\n\t\t\t\tdestroy_minion(side, sac_l)\n\t\t\t\tif is_game_over:\n\t\t\t\t\treturn true\n\t\t# 若目标放置列原本有非献祭随从且献祭腾出了其他空位，则自动选在空位上\n\t\tif card.data.type == \"minion\" and board[side][target_lane] != null:\n\t\t\tfor l in sacrifice_lanes:\n\t\t\t\tif board[side][l] == null:\n\t\t\t\t\ttarget_lane = l\n\t\t\t\t\tbreak\n\n\t# 2. 扣除能量与骨头，移除手牌，更新本回合连击计数\n\tst[\"energy\"] = int(st[\"energy\"]) - need_energy\n\tst[\"bones\"] = int(st[\"bones\"]) - card.data.bones\n\tif card.data.type == \"minion\" and card.data.race == \"机械\" and int(st[\"next_mech_discount\"]) > 0:\n\t\tst[\"next_mech_discount\"] = 0\n\thand.erase(card)\n\tst[\"cards_played_this_turn\"] = int(st[\"cards_played_this_turn\"]) + 1\n\tvar combo_count: int = int(st[\"cards_played_this_turn\"])\n\n\tAudioManager.play_sfx(\"play_card\")\n\t_log(\"🃏 %s打出了【%s】（当前连击数：%d）\" % [\"我方\" if side == PLAYER else \"敌方\", card.data.name, combo_count])\n\n\t# 3. 按随从或法术分支执行\n\tif card.data.type == \"minion\":\n\t\t# 若指定列仍有随从，自动寻找最左侧空列\n\t\tif board[side][target_lane] != null:\n\t\t\ttarget_lane = find_first_empty_lane(side)\n\t\tif target_lane == -1:\n\t\t\treturn false\n\t\t_place_minion_on_board(side, card, target_lane)\n\t\t# 触发【入场曲】（仅从手牌打出时触发）\n\t\t_resolve_fanfare(side, card, target_lane, effect_target_lane, choice_index, hand_target_uid)\n\t\t# 随从放置到战场后等待点击「回合结束」时再统一按序自动发起攻击\n\telif card.data.type == \"spell\":\n\t\t_resolve_spell(side, card, effect_target_lane, is_enhanced, combo_count)\n\t\t# 根据思维导图费用规则：「场上随从被破坏或者使用法术卡时骨头+1」\n\t\tadd_bones(side, 1, \"使用法术\")\n\n\tstate_updated.emit()\n\treturn true\n\n## 将随从放置或召唤到指定列，并触发【随从进场时】与赛博牧羊人光环\nfunc _place_minion_on_board(side: int, minion: CardInstance, lane: int) -> void:\n\tboard[side][lane] = minion\n\t_enter_seq += 1\n\tminion.lane_index = lane\n\tminion.enter_order = _enter_seq\n\tfloating_text_requested.emit(side, lane, \"入场\", Color(0.4, 0.85, 1.0))\n\n\t# 检查己方场上的「赛博牧羊人」光环：每当机械随从进入战场时，使其获得 +1/+1\n\tif minion.data.race == \"机械\":\n\t\tfor l in range(LANES):\n\t\t\tvar ally: CardInstance = board[side][l]\n\t\t\tif ally != null and ally != minion and ally.data.id == \"cmwbxu7u3tpyo\":\n\t\t\t\tminion.add_stats(1, 1)\n\t\t\t\t_log(\"⚡ 【赛博牧羊人】使新入场的机械随从【%s】获得 +1/+1！\" % minion.data.name)\n\t\t\t\tfloating_text_requested.emit(side, lane, \"+1/+1\", Color(0.3, 1.0, 0.5))\n\n\t# 检查该随从自身的【随从进场时】词条（如「摇滚骷髅吉他手」进场召唤4个骷髅，不论从手牌还是瞬念召唤均触发）\n\tif minion.data.id == \"cmwbyp6f419ju\":\n\t\t_log(\"🎸 【摇滚骷髅吉他手】随从进场时：召唤 4 个【骷髅】到战场上！\")\n\t\tsummon_by_name(side, \"骷髅\", 4)\n\n## 在首个空余列召唤指定卡牌名称/ID的随从（从别的途径入场，不触发入场曲，但入场后立刻攻击）\nfunc summon_by_name(side: int, card_name_or_id: String, count: int = 1, auto_attack: bool = false) -> Array[CardInstance]:\n\tvar summoned: Array[CardInstance] = []\n\tfor i in range(count):\n\t\tvar empty_l: int = find_first_empty_lane(side)\n\t\tif empty_l == -1:\n\t\t\tbreak\n\t\tvar inst: CardInstance = CardDatabase.create_instance(card_name_or_id, side)\n\t\tif inst != null:\n\t\t\t_place_minion_on_board(side, inst, empty_l)\n\t\t\tsummoned.append(inst)\n\t\t\tif auto_attack and not is_game_over and board[side][empty_l] == inst:\n\t\t\t\tperform_minion_combat(side, empty_l)\n\treturn summoned\n\n## 查找指定阵营最左侧的空列索引（若满场返回 -1）\nfunc find_first_empty_lane(side: int) -> int:\n\tfor l in range(LANES):\n\t\tif board[side][l] == null:\n\t\t\treturn l\n\treturn -1\n\n## 结算全部随从的【入场曲】效果（精确覆盖 JSON 中的全部入场曲卡牌）\nfunc _resolve_fanfare(\n\tside: int,\n\tcard: CardInstance,\n\tlane: int,\n\teffect_target_lane: int,\n\tchoice_index: int,\n\thand_target_uid: int\n) -> void:\n\tvar st: Dictionary = leaders[side]\n\tvar opp_side: int = 1 - side\n\tmatch card.data.id:\n\t\t\"cmwas0lke5oiw\": # 高性能引擎机甲：【抉择】(1) 招募_能量4 仅限机械 发动两次；(2) 亡者召还_能量4 仅限机械 发动两次\n\t\t\tif choice_index == 0:\n\t\t\t\t_log(\"⚙️ 【高性能引擎机甲】发动抉择（1）：连续两次【招募_能量4】机械随从！\")\n\t\t\t\trecruit_minion(side, 4, \"机械\")\n\t\t\t\trecruit_minion(side, 4, \"机械\")\n\t\t\telse:\n\t\t\t\t_log(\"⚙️ 【高性能引擎机甲】发动抉择（2）：连续两次【亡者召还_能量4】机械随从！\")\n\t\t\t\treanimate_minion(side, 4, \"机械\")\n\t\t\t\treanimate_minion(side, 4, \"机械\")\n\n\t\t\"cmwbxdn7tcvde\": # 滑板跃迁手：选择一张手牌洗入牌库，抽取一张卡牌\n\t\t\tvar hand: Array = st[\"hand\"]\n\t\t\tif not hand.is_empty():\n\t\t\t\tvar target_c: CardInstance = null\n\t\t\t\tfor hc in hand:\n\t\t\t\t\tif hc.uid == hand_target_uid:\n\t\t\t\t\t\ttarget_c = hc\n\t\t\t\t\t\tbreak\n\t\t\t\tif target_c == null:\n\t\t\t\t\ttarget_c = hand[0]\n\t\t\t\thand.erase(target_c)\n\t\t\t\tst[\"deck\"].append(target_c)\n\t\t\t\tst[\"deck\"].shuffle()\n\t\t\t\t_log(\"🛹 【滑板跃迁手】将手牌【%s】洗回牌库并抽取 1 张卡牌。\" % target_c.data.name)\n\t\t\t\tdraw_card(side, false)\n\n\t\t\"cmwby8v9c918f\": # 爆炸羊狂热者：给予手牌中所有电子羊谢幕曲【对对手战场所有随从和主战者分配2点伤害】\n\t\t\tvar buffed_cnt: int = 0\n\t\t\tfor hc in st[\"hand\"]:\n\t\t\t\tif hc.data.id == \"cmwby0dy7g2pc\" or hc.data.name == \"电子羊\":\n\t\t\t\t\thc.extra_last_words.append({\n\t\t\t\t\t\t\"type\": \"boom_sheep\",\n\t\t\t\t\t\t\"desc\": \"对敌方场上所有随从与主战者分配2点伤害\"\n\t\t\t\t\t})\n\t\t\t\t\tbuffed_cnt += 1\n\t\t\t_log(\"💣 【爆炸羊狂热者】为手牌中 %d 张【电子羊】附加了爆破谢幕曲！\" % buffed_cnt)\n\n\t\t\"cmwbyhrbei4w8\": # 增殖机甲：召唤一张和增殖机甲同名的卡牌加入战场\n\t\t\t_log(\"🤖 【增殖机甲】入场曲：召唤 1 张同名【增殖机甲】加入战场！\")\n\t\t\tsummon_by_name(side, \"cmwbyhrbei4w8\", 1)\n\n\t\t\"cmwc0t61ade7b\": # 血偿者：抽取1张卡牌，选择对手战场上1个随从对其造成3点伤害\n\t\t\tdraw_card(side, false)\n\t\t\tif effect_target_lane >= 0 and effect_target_lane < LANES and board[opp_side][effect_target_lane] != null:\n\t\t\t\t_log(\"🩸 【血偿者】入场曲：抽取 1 张牌并对【%s】造成 3 点伤害！\" % board[opp_side][effect_target_lane].data.name)\n\t\t\t\tdeal_damage_to_minion(opp_side, effect_target_lane, 3)\n\n\t\t\"cmwc2n4p68ewm\": # 装甲堡垒：若你手牌中的机械卡大于6张，召唤3个电子羊并使场上所有电子羊获得守护\n\t\t\tvar mech_in_hand: int = _count_mech_in_hand(side)\n\t\t\tif mech_in_hand >= 6:\n\t\t\t\t_log(\"🛡️ 【装甲堡垒】手牌机械卡达 %d 张！召唤 3 个【电子羊】并赋予全场友方电子羊【守护】！\" % mech_in_hand)\n\t\t\t\tsummon_by_name(side, \"电子羊\", 3)\n\t\t\t\tfor l in range(LANES):\n\t\t\t\t\tvar m: CardInstance = board[side][l]\n\t\t\t\t\tif m != null and (m.data.id == \"cmwby0dy7g2pc\" or m.data.name == \"电子羊\"):\n\t\t\t\t\t\tm.grant_kw(\"守护\", 1)\n\n\t\t\"cmwc2wbcgbqvl\": # 铜壳瓢虫：你使用的下一张机械随从卡能量-1\n\t\t\tst[\"next_mech_discount\"] = int(st[\"next_mech_discount\"]) + 1\n\t\t\t_log(\"🐞 【铜壳瓢虫】入场曲：下一张机械随从能量消耗 -1！\")\n\n\t\t\"cmwc3gozg0rat\": # 超载机皇：【抉择】(1) 其他机械随从获得+2/+2；(2) 对最多三个敌方随从造成x点伤害（x=手牌机械卡张数）\n\t\t\tif choice_index == 0:\n\t\t\t\t_log(\"👑 【超载机皇】发动抉择（1）：其他友方机械随从全部获得 +2/+2！\")\n\t\t\t\tfor l in range(LANES):\n\t\t\t\t\tvar ally: CardInstance = board[side][l]\n\t\t\t\t\tif ally != null and ally != card and ally.data.race == \"机械\":\n\t\t\t\t\t\tally.add_stats(2, 2)\n\t\t\t\t\t\tfloating_text_requested.emit(side, l, \"+2/+2\", Color(1.0, 0.85, 0.25))\n\t\t\telse:\n\t\t\t\tvar x_dmg: int = _count_mech_in_hand(side)\n\t\t\t\t_log(\"👑 【超载机皇】发动抉择（2）：手牌共有 %d 张机械卡，对最多 3 个敌方随从造成 %d 点伤害！\" % [x_dmg, x_dmg])\n\t\t\t\tif x_dmg > 0:\n\t\t\t\t\tvar hit_cnt: int = 0\n\t\t\t\t\tfor l in range(LANES):\n\t\t\t\t\t\tif board[opp_side][l] != null and hit_cnt < 3:\n\t\t\t\t\t\t\thit_cnt += 1\n\t\t\t\t\t\t\tdeal_damage_to_minion(opp_side, l, x_dmg)\n\n\t\t\"cmwc8tup5d1xt\": # 磁力拼装机械：若你手牌中的机械卡大于6张，随机从守护、飞行、防空、灵气、毁灭、虹吸、位移、屏障中获得三个词条\n\t\t\tvar mech_cnt: int = _count_mech_in_hand(side)\n\t\t\tif mech_cnt >= 6:\n\t\t\t\tvar pool: Array[String] = [\"守护\", \"飞行\", \"防空\", \"灵气\", \"毁灭\", \"虹吸\", \"位移\", \"屏障\"]\n\t\t\t\tpool.shuffle()\n\t\t\t\tvar gained: PackedStringArray = []\n\t\t\t\tfor i in range(3):\n\t\t\t\t\tcard.grant_kw(pool[i], 1)\n\t\t\t\t\tgained.append(pool[i])\n\t\t\t\t_log(\"🧲 【磁力拼装机械】获得随机 3 个词条：%s！\" % \"、\".join(gained))\n\n## 结算全部法术卡效果\nfunc _resolve_spell(side: int, card: CardInstance, target_lane: int, is_enhanced: bool, combo_count: int) -> void:\n\tvar opp_side: int = 1 - side\n\tmatch card.data.id:\n\t\t\"cmwcah8st1lar\": # 神圣法典：选择1个生命值3以下敌方随从，使其消失\n\t\t\tif target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:\n\t\t\t\tvar m: CardInstance = board[opp_side][target_lane]\n\t\t\t\tif m.current_hp <= 3:\n\t\t\t\t\tbanish_minion(opp_side, target_lane)\n\n\t\t\"cmwcalky6itcu\": # 烟消云散：选择1个敌方随从使其和与其同名的所有敌方随从消失\n\t\t\tif target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:\n\t\t\t\tvar target_name: String = board[opp_side][target_lane].data.name\n\t\t\t\tfor l in range(LANES):\n\t\t\t\t\tif board[opp_side][l] != null and board[opp_side][l].data.name == target_name:\n\t\t\t\t\t\tbanish_minion(opp_side, l)\n\n\t\t\"cmwcaqbzuvvcx\": # 转生苹果：选择1个友方随从，使其获得谢幕曲【召唤1个自己同名的随从到战场上】\n\t\t\tif target_lane >= 0 and target_lane < LANES and board[side][target_lane] != null:\n\t\t\t\tvar ally: CardInstance = board[side][target_lane]\n\t\t\t\tally.extra_last_words.append({\n\t\t\t\t\t\"type\": \"rebirth_self\",\n\t\t\t\t\t\"card_id\": ally.data.id,\n\t\t\t\t\t\"desc\": \"召唤1个【%s】到战场上\" % ally.data.name\n\t\t\t\t})\n\t\t\t\t_log(\"🍎 【转生苹果】赋予了【%s】同名复活谢幕曲！\" % ally.data.name)\n\t\t\t\tfloating_text_requested.emit(side, target_lane, \"+转生谢幕曲\", Color(0.4, 1.0, 0.5))\n\n\t\t\"cmwcb1izpxl7e\": # 连锁飞刃：【连击_3】改为造成5点伤害；选择1个敌方随从造成3点伤害\n\t\t\tvar dmg: int = 5 if combo_count >= 3 else 3\n\t\t\tif target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:\n\t\t\t\t_log(\"🗡️ 【连锁飞刃】对【%s】造成 %d 点伤害！\" % [board[opp_side][target_lane].data.name, dmg])\n\t\t\t\tdeal_damage_to_minion(opp_side, target_lane, dmg)\n\n\t\t\"cmwcba1blx523\": # 炽炎之术：选择1个敌方随从造成3点伤害；【爆能强化_能量5】改为对敌方随从全体造成3点伤害\n\t\t\tif is_enhanced:\n\t\t\t\t_log(\"🔥 【炽炎之术（爆能强化5）】对敌方全体随从造成 3 点伤害！\")\n\t\t\t\tfor l in range(LANES):\n\t\t\t\t\tif board[opp_side][l] != null:\n\t\t\t\t\t\tdeal_damage_to_minion(opp_side, l, 3)\n\t\t\telif target_lane >= 0 and target_lane < LANES and board[opp_side][target_lane] != null:\n\t\t\t\t_log(\"🔥 【炽炎之术】对【%s】造成 3 点伤害！\" % board[opp_side][target_lane].data.name)\n\t\t\t\tdeal_damage_to_minion(opp_side, target_lane, 3)\n\n## 激活场上随从的【启动】能力（如「赛博牧羊人」消耗1点能量将2张电子羊加入手牌）\nfunc activate_minion_ability(side: int, lane: int) -> bool:\n\tvar m: CardInstance = board[side][lane]\n\tif m == null or m.activated_this_turn:\n\t\treturn false\n\tvar st: Dictionary = leaders[side]\n\tfor kw in m.data.keywords:\n\t\tif str(kw.get(\"k\", \"\")) == \"启动\":\n\t\t\tvar cost_dict: Dictionary = kw.get(\"cost\", {})\n\t\t\tvar e_cost: int = int(cost_dict.get(\"energy\", 0))\n\t\t\tvar b_cost: int = int(cost_dict.get(\"bones\", 0))\n\t\t\tif int(st[\"energy\"]) < e_cost or int(st[\"bones\"]) < b_cost:\n\t\t\t\treturn false\n\t\t\tst[\"energy\"] = int(st[\"energy\"]) - e_cost\n\t\t\tst[\"bones\"] = int(st[\"bones\"]) - b_cost\n\t\t\tm.activated_this_turn = true\n\t\t\tif m.data.id == \"cmwbxu7u3tpyo\": # 赛博牧羊人\n\t\t\t\t_log(\"⚡ 发动【赛博牧羊人】启动能力：消耗 1 点能量，将 2 张【电子羊】加入手牌！\")\n\t\t\t\tadd_card_to_hand(side, \"电子羊\", 2)\n\t\t\tAudioManager.play_sfx(\"buff\")\n\t\t\tstate_updated.emit()\n\t\t\treturn true\n\treturn false\n\n## 结算单个随从的战道交战（含多重攻击、两侧/三侧/全体攻击、飞行与防空、守护横移拦截、毁灭、荆棘、虹吸、位移）\nfunc perform_minion_combat(attacker_side: int, lane: int) -> void:\n\tvar attacker: CardInstance = board[attacker_side][lane]\n\tif attacker == null or is_game_over:\n\t\treturn\n\t# 思维导图规则：「攻击为0的随从不会进行攻击，具有攻击力后开始攻击」\n\tif attacker.current_atk <= 0:\n\t\treturn\n\n\tvar multi_times: int = max(1, attacker.get_kw_val(\"多重攻击\"))\n\tfor hit_idx in range(multi_times):\n\t\tif is_game_over or board[attacker_side][lane] != attacker or attacker.current_atk <= 0:\n\t\t\tbreak\n\t\t_execute_single_attack_swing(attacker_side, lane, attacker)\n\n\t# 攻击结束后若随从仍在场且具有【潜行】，解除潜行；若具有【位移】，执行左右横移\n\tif not is_game_over and board[attacker_side][lane] == attacker:\n\t\tif attacker.has_kw(\"潜行\"):\n\t\t\tattacker.remove_kw(\"潜行\")\n\t\tif attacker.has_kw(\"位移\"):\n\t\t\t_process_minion_shift(attacker_side, lane, attacker)\n\nfunc _execute_single_attack_swing(attacker_side: int, lane: int, attacker: CardInstance) -> void:\n\tvar opp_side: int = 1 - attacker_side\n\t# 1. 确定本次攻击的目标列集合（支持全体攻击、三侧攻击、两侧攻击、常规前方单列攻击）\n\tvar target_lanes: Array[int] = []\n\tvar also_fly_hit_leader: bool = false\n\tif attacker.has_kw(\"全体攻击\"):\n\t\tfor l in range(LANES):\n\t\t\tif board[opp_side][l] != null:\n\t\t\t\ttarget_lanes.append(l)\n\t\tvar front_def: CardInstance = board[opp_side][lane]\n\t\tif attacker.has_kw(\"飞行\") and (front_def == null or not front_def.has_kw(\"防空\")):\n\t\t\talso_fly_hit_leader = true\n\t\telif target_lanes.is_empty():\n\t\t\talso_fly_hit_leader = true\n\telif attacker.has_kw(\"三侧攻击\"):\n\t\tfor dl in [-1, 0, 1]:\n\t\t\tvar tl: int = lane + dl\n\t\t\tif tl >= 0 and tl < LANES:\n\t\t\t\ttarget_lanes.append(tl)\n\telif attacker.has_kw(\"两侧攻击\"):\n\t\tfor dl in [-1, 1]:\n\t\t\tvar tl: int = lane + dl\n\t\t\tif tl >= 0 and tl < LANES:\n\t\t\t\ttarget_lanes.append(tl)\n\telse:\n\t\ttarget_lanes.append(lane)\n\n\t# 2. 若是全体攻击，先对所有在场敌方随从造成伤害，若同时触发飞行直击或空场则对敌方主战者造成伤害\n\tif attacker.has_kw(\"全体攻击\"):\n\t\tfor tl in target_lanes:\n\t\t\tif is_game_over or board[attacker_side][lane] != attacker:\n\t\t\t\tbreak\n\t\t\tvar def_m: CardInstance = board[opp_side][tl]\n\t\t\tif def_m != null:\n\t\t\t\tattack_anim_requested.emit(attacker_side, lane, opp_side, tl)\n\t\t\t\tvar dealt: int = deal_damage_to_minion(opp_side, tl, attacker.current_atk, attacker)\n\t\t\t\tif def_m != null and def_m.has_kw(\"荆棘\") and dealt > 0:\n\t\t\t\t\tdeal_damage_to_minion(attacker_side, lane, def_m.get_kw_val(\"荆棘\"), def_m)\n\t\tif also_fly_hit_leader and not is_game_over and board[attacker_side][lane] == attacker:\n\t\t\tattack_anim_requested.emit(attacker_side, lane, opp_side, -1)\n\t\t\tdeal_damage_to_leader(opp_side, attacker.current_atk, attacker)\n\t\treturn\n\n\t# 2. 依次对每个目标列执行打击\n\tfor tl in target_lanes:\n\t\tif is_game_over or board[attacker_side][lane] != attacker:\n\t\t\tbreak\n\t\tvar defender: CardInstance = board[opp_side][tl]\n\n\t\t# 检查【守护】自动横移机制：「在对方随从直接攻击主战者时，如果场上有空位，则该随从自动移动到该位置进行交战」\n\t\tif defender == null:\n\t\t\tvar guard_lane: int = _find_movable_guard_lane(opp_side, tl)\n\t\t\tif guard_lane != -1:\n\t\t\t\tdefender = board[opp_side][guard_lane]\n\t\t\t\tboard[opp_side][guard_lane] = null\n\t\t\t\tboard[opp_side][tl] = defender\n\t\t\t\tdefender.lane_index = tl\n\t\t\t\t_log(\"🛡️ 敌方【%s】触发【守护】，自动横移至第 %d 列拦截攻击！\" % [defender.data.name, tl + 1])\n\t\t\t\tguard_move_requested.emit(opp_side, guard_lane, tl)\n\n\t\t# 判断是否越过随从直接攻击主战者（【飞行】能越过没有【防空】的随从）\n\t\tvar attack_leader_directly: bool = false\n\t\tif defender == null:\n\t\t\tattack_leader_directly = true\n\t\telif attacker.has_kw(\"飞行\") and not defender.has_kw(\"防空\"):\n\t\t\tattack_leader_directly = true\n\n\t\tAudioManager.play_sfx(\"hit\")\n\t\tif attack_leader_directly:\n\t\t\tattack_anim_requested.emit(attacker_side, lane, opp_side, -1)\n\t\t\tdeal_damage_to_leader(opp_side, attacker.current_atk, attacker)\n\t\telse:\n\t\t\tattack_anim_requested.emit(attacker_side, lane, opp_side, tl)\n\t\t\t# 思维导图规则：「随从入场可以立刻攻击，攻击敌方随从不会受到敌方攻击力伤害，生命值为0时消灭」\n\t\t\tvar dmg_dealt: int = deal_damage_to_minion(opp_side, tl, attacker.current_atk, attacker)\n\t\t\t# 若防守方具有【荆棘】，受到伤害时对攻击者进行反伤\n\t\t\tif defender != null and defender.has_kw(\"荆棘\") and dmg_dealt > 0:\n\t\t\t\tvar thorn_dmg: int = defender.get_kw_val(\"荆棘\")\n\t\t\t\t_log(\"🌵 【%s】的【荆棘_%d】对【%s】造成 %d 点反伤！\" % [defender.data.name, thorn_dmg, attacker.data.name, thorn_dmg])\n\t\t\t\tdeal_damage_to_minion(attacker_side, lane, thorn_dmg, defender)\n\n## 寻找可横移到空位拦截主战者直伤的【守护】随从所在列\nfunc _find_movable_guard_lane(defender_side: int, empty_target_lane: int) -> int:\n\tif board[defender_side][empty_target_lane] != null:\n\t\treturn -1\n\tvar best_lane: int = -1\n\tvar best_dist: int = 99\n\tfor l in range(LANES):\n\t\tvar m: CardInstance = board[defender_side][l]\n\t\tif m != null and m.has_kw(\"守护\") and not m.has_kw(\"潜行\"):\n\t\t\tvar d: int = absi(l - empty_target_lane)\n\t\t\tif d < best_dist:\n\t\t\t\tbest_dist = d\n\t\t\t\tbest_lane = l\n\treturn best_lane\n\n## 处理【位移】词条：攻击结束后往右移动一格，触底或被随从阻挡则改为向左\nfunc _process_minion_shift(side: int, lane: int, minion: CardInstance) -> void:\n\tvar next_lane: int = lane + minion.shift_dir\n\tif next_lane < 0 or next_lane >= LANES or board[side][next_lane] != null:\n\t\tminion.shift_dir = -minion.shift_dir\n\t\tnext_lane = lane + minion.shift_dir\n\tif next_lane >= 0 and next_lane < LANES and board[side][next_lane] == null:\n\t\tboard[side][lane] = null\n\t\tboard[side][next_lane] = minion\n\t\tminion.lane_index = next_lane\n\t\t_log(\"↔️ 【%s】触发【位移】移动至第 %d 列。\" % [minion.data.name, next_lane + 1])\n\n## 对指定随从造成伤害（含【屏障】抵挡、【毁灭】必杀与【虹吸】吸血）\nfunc deal_damage_to_minion(target_side: int, lane: int, amount: int, source_minion: CardInstance = null) -> int:\n\tif amount <= 0:\n\t\treturn 0\n\tvar target: CardInstance = board[target_side][lane]\n\tif target == null:\n\t\treturn 0\n\t# 检查【屏障】：抵挡受到的第一次伤害，至少受到1点伤害时屏障消失\n\tif target.has_kw(\"屏障\"):\n\t\ttarget.remove_kw(\"屏障\")\n\t\t_log(\"🫧 【%s】的【屏障】抵挡了本次 %d 点伤害！\" % [target.data.name, amount])\n\t\tfloating_text_requested.emit(target_side, lane, \"屏障抵挡\", Color(0.4, 0.9, 1.0))\n\t\treturn 0\n\n\ttarget.current_hp -= amount\n\tfloating_text_requested.emit(target_side, lane, \"-%d\" % amount, Color(1.0, 0.3, 0.35))\n\n\t# 检查攻击者是否具有【虹吸】\n\tif source_minion != null and source_minion.has_kw(\"虹吸\"):\n\t\theal_leader(source_minion.owner_id, amount)\n\n\t# 检查攻击者是否具有【毁灭】：「直接消灭受到该随从伤害的随从」\n\tif target.current_hp <= 0 or (source_minion != null and source_minion.has_kw(\"毁灭\")):\n\t\tif source_minion != null and source_minion.has_kw(\"毁灭\") and target.current_hp > 0:\n\t\t\t_log(\"☠️ 【%s】的【毁灭】词条直接消灭了受伤的【%s】！\" % [source_minion.data.name, target.data.name])\n\t\tdestroy_minion(target_side, lane)\n\treturn amount\n\n## 对指定主战者造成伤害\nfunc deal_damage_to_leader(target_side: int, amount: int, source_minion: CardInstance = null) -> void:\n\tif amount <= 0 or is_game_over:\n\t\treturn\n\tvar st: Dictionary = leaders[target_side]\n\tst[\"hp\"] = int(st[\"hp\"]) - amount\n\tfloating_text_requested.emit(target_side, -1, \"-%d\" % amount, Color(1.0, 0.25, 0.3))\n\t_log(\"💥 %s主战者受到 %d 点伤害（剩余生命：%d）\" % [\"我方\" if target_side == PLAYER else \"敌方\", amount, int(st[\"hp\"])])\n\tif source_minion != null and source_minion.has_kw(\"虹吸\"):\n\t\theal_leader(source_minion.owner_id, amount)\n\tif int(st[\"hp\"]) <= 0:\n\t\tis_game_over = true\n\t\tvar winner: int = 1 - target_side\n\t\tAudioManager.play_sfx(\"victory\")\n\t\t_log(\"🏆 对战结束！%s获胜！\" % (\"我方\" if winner == PLAYER else \"敌方\"))\n\t\tgame_over_triggered.emit(winner, \"%s主战者生命值归零\" % (\"敌方\" if winner == PLAYER else \"我方\"))\n\n## 为主战者恢复生命值\nfunc heal_leader(side: int, amount: int) -> void:\n\tvar st: Dictionary = leaders[side]\n\tvar old_hp: int = int(st[\"hp\"])\n\tst[\"hp\"] = min(int(st[\"max_hp\"]), old_hp + amount)\n\tif int(st[\"hp\"]) > old_hp:\n\t\tfloating_text_requested.emit(side, -1, \"+%d\" % (int(st[\"hp\"]) - old_hp), Color(0.3, 1.0, 0.5))\n\n## 增加骨头资源\nfunc add_bones(side: int, amount: int, reason: String = \"\") -> void:\n\tif amount <= 0:\n\t\treturn\n\tvar st: Dictionary = leaders[side]\n\tst[\"bones\"] = int(st[\"bones\"]) + amount\n\tif reason != \"\":\n\t\t_log(\"🦴 %s获得 +%d 骨头（%s，当前共 %d 骨头）\" % [\"我方\" if side == PLAYER else \"敌方\", amount, reason, int(st[\"bones\"])])\n\n## 破坏场上随从：送入墓地、骨头+1、触发【谢幕曲】与【随从离场时】\nfunc destroy_minion(side: int, lane: int) -> void:\n\tvar m: CardInstance = board[side][lane]\n\tif m == null:\n\t\treturn\n\tboard[side][lane] = null\n\tm.lane_index = -1\n\tvar st: Dictionary = leaders[side]\n\tst[\"graveyard\"].append(m.data)\n\tif m.has_any_last_words():\n\t\tst[\"destroyed_last_words_count\"] = int(st[\"destroyed_last_words_count\"]) + 1\n\t# 思维导图规则：「场上随从被破坏或者使用法术卡时骨头+1」\n\tadd_bones(side, 1, \"【%s】被破坏\" % m.data.name)\n\t_resolve_last_words(side, lane, m)\n\n## 消失场上随从：不进入墓地、不增加骨头、不触发谢幕曲\nfunc banish_minion(side: int, lane: int) -> void:\n\tvar m: CardInstance = board[side][lane]\n\tif m == null:\n\t\treturn\n\tboard[side][lane] = null\n\tm.lane_index = -1\n\t_log(\"✨ 【%s】被消失（不触发谢幕曲且不进入墓地）。\" % m.data.name)\n\tfloating_text_requested.emit(side, lane, \"消失\", Color(0.85, 0.7, 1.0))\n\n## 结算全部随从的【谢幕曲】效果\nfunc _resolve_last_words(side: int, lane: int, m: CardInstance) -> void:\n\tvar st: Dictionary = leaders[side]\n\tvar opp_side: int = 1 - side\n\tmatch m.data.id:\n\t\t\"cmwbvfqe5en3l\": # 通用载人机甲：【谢幕曲】【招募_能量2】\n\t\t\t_log(\"⚙️ 【通用载人机甲】谢幕曲：发动【招募_能量2】！\")\n\t\t\trecruit_minion(side, 2, \"\")\n\t\t\"cmwbvnpfgwo7a\", \"cmwbwne297mmg\", \"cmwc2zlhaxdtj\": # 铁皮打手 / 发条侍从 / 齿轮学徒：将1张电子羊加入手牌\n\t\t\t_log(\"🐑 【%s】谢幕曲：将 1 张【电子羊】加入手牌。\" % m.data.name)\n\t\t\tadd_card_to_hand(side, \"电子羊\", 1)\n\t\t\"cmwbwg3kwqfkq\": # 飞轮信使：下个回合开始时，从牌库抽取一张机械随从\n\t\t\tst[\"delayed_mech_draws\"] = int(st[\"delayed_mech_draws\"]) + 1\n\t\t\t_log(\"📨 【飞轮信使】谢幕曲：预约下回合开始时抽取 1 张机械随从。\")\n\t\t\"cmwbyp6f419ju\": # 摇滚骷髅吉他手：谢幕曲召唤四个骷髅到战场上\n\t\t\t_log(\"🎸 【摇滚骷髅吉他手】谢幕曲：召唤 4 个【骷髅】到战场上！\")\n\t\t\tsummon_by_name(side, \"骷髅\", 4)\n\t\t\"cmwc0auyporsj\": # 骸骨兽：召唤两个骷髅到战场上\n\t\t\t_log(\"💀 【骸骨兽】谢幕曲：召唤 2 个【骷髅】到战场上！\")\n\t\t\tsummon_by_name(side, \"骷髅\", 2)\n\t\t\"cmwc0t61ade7b\": # 血偿者：谢幕曲抽取1张卡牌\n\t\t\t_log(\"🩸 【血偿者】谢幕曲：抽取 1 张卡牌。\")\n\t\t\tdraw_card(side, false)\n\t\t\"cmwc33vo8ohrw\": # 发条龙：召唤2个电子羊到战场上\n\t\t\t_log(\"🐉 【发条龙】谢幕曲：召唤 2 个【电子羊】到战场上！\")\n\t\t\tsummon_by_name(side, \"电子羊\", 2)\n\t\t\"cmwc3or2zf7ft\": # 万齿战车：【谢幕曲】亡者召还_能量6/4/2（仅限机械）\n\t\t\t_log(\"🚜 【万齿战车】谢幕曲：依次发动能量 6 / 4 / 2 的机械【亡者召还】！\")\n\t\t\treanimate_minion(side, 6, \"机械\")\n\t\t\treanimate_minion(side, 4, \"机械\")\n\t\t\treanimate_minion(side, 2, \"机械\")\n\t\t\"cmwc97xb64vc6\", \"cmwc9mbry93dx\": # 尸兵 / 骸骨犬：谢幕曲骨头+2\n\t\t\tadd_bones(side, 2, \"【%s】谢幕曲\" % m.data.name)\n\t\t\"cmwc9ua0fd6of\": # 骨龙：谢幕曲骨头+3，将1张和骨龙同名的随从加入手牌\n\t\t\tadd_bones(side, 3, \"【骨龙】谢幕曲\")\n\t\t\tadd_card_to_hand(side, \"骨龙\", 1)\n\n\t# 结算动态附加的额外谢幕曲（如「爆炸羊狂热者」赋予的爆破2伤、「转生苹果」赋予的同名复活）\n\tfor extra in m.extra_last_words:\n\t\tvar etype: String = str(extra.get(\"type\", \"\"))\n\t\tif etype == \"boom_sheep\":\n\t\t\t_log(\"💥 【电子羊】触发附加谢幕曲：按入场先后顺序对敌方随从和主战者分配 2 点伤害！\")\n\t\t\tdistribute_damage(opp_side, 2, true)\n\t\telif etype == \"rebirth_self\":\n\t\t\tvar cid: String = str(extra.get(\"card_id\", m.data.id))\n\t\t\t_log(\"🍎 触发【转生苹果】谢幕曲：重新召唤【%s】！\" % m.data.name)\n\t\t\tsummon_by_name(side, cid, 1)\n\n## 【招募】机制：从己方牌库中随机召唤 1 张能量费用 <= max_energy 且符合 race_filter 的随从到战场上\nfunc recruit_minion(side: int, max_energy: int, race_filter: String = \"\") -> CardInstance:\n\tvar empty_l: int = find_first_empty_lane(side)\n\tif empty_l == -1:\n\t\treturn null\n\tvar st: Dictionary = leaders[side]\n\tvar deck: Array = st[\"deck\"]\n\tvar candidates: Array[int] = []\n\tfor i in range(deck.size()):\n\t\tvar c: CardInstance = deck[i]\n\t\tif c.data.type == \"minion\" and c.data.energy <= max_energy:\n\t\t\tif race_filter == \"\" or c.data.race == race_filter:\n\t\t\t\tcandidates.append(i)\n\tif candidates.is_empty():\n\t\treturn null\n\t# 优先招募费用最高者\n\tcandidates.sort_custom(func(ia: int, ib: int) -> bool:\n\t\treturn deck[ia].data.energy > deck[ib].data.energy\n\t)\n\tvar chosen_idx: int = candidates[0]\n\tvar inst: CardInstance = deck[chosen_idx]\n\tdeck.remove_at(chosen_idx)\n\t_log(\"📣 【招募】从牌库召唤了【%s】到第 %d 列！\" % [inst.data.name, empty_l + 1])\n\t_place_minion_on_board(side, inst, empty_l)\n\t# 招募/亡者召还入场的随从同样在回合结束时统一发起攻击\n\treturn inst\n\n## 【亡者召还】机制：从己方墓地中召唤 1 张能量费用 <= max_energy（优先最高费）且符合 race_filter 的随从到战场上\nfunc reanimate_minion(side: int, max_energy: int, race_filter: String = \"\") -> CardInstance:\n\tvar empty_l: int = find_first_empty_lane(side)\n\tif empty_l == -1:\n\t\treturn null\n\tvar st: Dictionary = leaders[side]\n\tvar grave: Array = st[\"graveyard\"]\n\tvar best_data: CardData = null\n\tfor cd in grave:\n\t\tif cd.type == \"minion\" and cd.energy <= max_energy:\n\t\t\tif race_filter == \"\" or cd.race == race_filter:\n\t\t\t\tif best_data == null or cd.energy > best_data.energy:\n\t\t\t\t\tbest_data = cd\n\tif best_data == null:\n\t\treturn null\n\tvar inst: CardInstance = CardDatabase.create_instance(best_data.id, side)\n\t_log(\"⚰️ 【亡者召还_%d】从墓地复活了【%s】到第 %d 列！\" % [max_energy, inst.data.name, empty_l + 1])\n\t_place_minion_on_board(side, inst, empty_l)\n\t# 招募/亡者召还入场的随从同样在回合结束时统一发起攻击\n\treturn inst\n\n## 结束当前阵营回合（严格遵循思维导图结算顺序：瞬念召唤先于回合结束时触发；己方从左到右，敌方从右到左）\nfunc end_turn(side: int) -> void:\n\tif is_game_over or active_side != side:\n\t\treturn\n\n\t# 0. 点击回合结束后，当前回合方场上随从按顺序（我方从左到右 0..4，敌方从右到左 4..0）自动攻击\n\tvar atk_order: Array[int] = _get_lane_order(side)\n\tfor lane in atk_order:\n\t\tif is_game_over:\n\t\t\treturn\n\t\tvar attacker: CardInstance = board[side][lane]\n\t\tif attacker != null:\n\t\t\tperform_minion_combat(side, lane)\n\n\t# 1. 结算【瞬念召唤】（思维导图规则：「瞬念召唤先于回合结束时触发」）\n\t_process_invocation_effects(side)\n\n\t# 2. 再按顺序（己方从左到右 0..4，敌方从右到左 4..0）结算场上随从的【回合结束时】效果\n\tvar order: Array[int] = _get_lane_order(side)\n\tfor lane in order:\n\t\tvar m: CardInstance = board[side][lane]\n\t\tif m != null:\n\t\t\t_trigger_turn_end_effects(side, lane, m)\n\n\t# 3. 切换到对手回合\n\tif not is_game_over:\n\t\tif side == PLAYER:\n\t\t\tbegin_turn(ENEMY)\n\t\t\t_run_enemy_ai_turn()\n\t\telse:\n\t\t\tturn_number += 1\n\t\t\tbegin_turn(PLAYER)\n\n## 检查并触发牌库中的【瞬念召唤】（如「魔导机兵少女」「摇滚骷髅吉他手」）\nfunc _process_invocation_effects(side: int) -> void:\n\tvar st: Dictionary = leaders[side]\n\tvar deck: Array = st[\"deck\"]\n\n\t# 检查 1：魔导机兵少女 (cmwbx0mq8qz7f) —— 如果己方场上拥有 5 个机械随从，破坏全部随从，从牌库召唤并获得全体攻击\n\tvar mech_board_count: int = 0\n\tfor l in range(LANES):\n\t\tif board[side][l] != null and board[side][l].data.race == \"机械\":\n\t\t\tmech_board_count += 1\n\tif mech_board_count == 5:\n\t\tfor i in range(deck.size()):\n\t\t\tvar c: CardInstance = deck[i]\n\t\t\tif c.data.id == \"cmwbx0mq8qz7f\":\n\t\t\t\tdeck.remove_at(i)\n\t\t\t\t_log(\"🌟 满足 5 机械条件！触发【魔导机兵少女】瞬念召唤：破坏己方全部随从，降临战场并对敌方全体随从造成4点伤害！\")\n\t\t\t\tfor l in range(LANES):\n\t\t\t\t\tif board[side][l] != null:\n\t\t\t\t\t\tdestroy_minion(side, l)\n\t\t\t\tvar empty_l: int = find_first_empty_lane(side)\n\t\t\t\tif empty_l != -1:\n\t\t\t\t\tc.grant_kw(\"全体攻击\", 1)\n\t\t\t\t\t_place_minion_on_board(side, c, empty_l)\n\t\t\t\t\tif not is_game_over and board[side][empty_l] == c:\n\t\t\t\t\t\tperform_minion_combat(side, empty_l)\n\t\t\t\tbreak\n\n\t# 检查 2：摇滚骷髅吉他手 (cmwbyp6f419ju) —— 若本次对战中自己被破坏的具有谢幕曲的随从 >= 10 个，召唤到战场上\n\tif int(st[\"destroyed_last_words_count\"]) >= 10 and find_first_empty_lane(side) != -1:\n\t\tfor i in range(deck.size()):\n\t\t\tvar c: CardInstance = deck[i]\n\t\t\tif c.data.id == \"cmwbyp6f419ju\":\n\t\t\t\tdeck.remove_at(i)\n\t\t\t\tvar empty_l: int = find_first_empty_lane(side)\n\t\t\t\t_log(\"🎸 已破坏 %d 个谢幕曲随从！触发【摇滚骷髅吉他手】瞬念召唤！\" % int(st[\"destroyed_last_words_count\"]))\n\t\t\t\t_place_minion_on_board(side, c, empty_l)\n\t\t\t\tif not is_game_over and board[side][empty_l] == c:\n\t\t\t\t\tperform_minion_combat(side, empty_l)\n\t\t\t\tbreak\n\nfunc _trigger_turn_start_effects(_side: int, _lane: int, _m: CardInstance) -> void:\n\tpass\n\nfunc _trigger_turn_end_effects(side: int, lane: int, m: CardInstance) -> void:\n\tif m.data.id == \"cmwc96kid9cw4\": # 掘墓者：【回合结束时】骨头+1\n\t\tadd_bones(side, 1, \"【掘墓者】回合结束\")\n\t\tfloating_text_requested.emit(side, lane, \"骨头+1\", Color(0.95, 0.9, 0.75))\n\nfunc _get_lane_order(side: int) -> Array[int]:\n\tif side == PLAYER:\n\t\treturn [0, 1, 2, 3, 4]\n\treturn [4, 3, 2, 1, 0]\n\nfunc _count_mech_in_hand(side: int) -> int:\n\tvar cnt: int = 0\n\tfor c in leaders[side][\"hand\"]:\n\t\tif c.data.race == \"机械\":\n\t\t\tcnt += 1\n\treturn cnt\n\n## 智能 AI 对手出牌与决策逻辑\nfunc _run_enemy_ai_turn() -> void:\n\tif is_game_over:\n\t\treturn\n\tvar st: Dictionary = leaders[ENEMY]\n\tvar acted: bool = true\n\twhile acted and not is_game_over:\n\t\tacted = false\n\t\tvar hand: Array = st[\"hand\"]\n\t\tfor c in hand.duplicate():\n\t\t\tvar check: Dictionary = can_play_card(ENEMY, c)\n\t\t\tif not bool(check.get(\"ok\", false)):\n\t\t\t\tcontinue\n\t\t\tvar is_enh: bool = (will_trigger_enhance(ENEMY, c) > 0)\n\t\t\tvar req: String = get_card_target_requirement(c, is_enh)\n\t\t\tvar eff_target: int = -1\n\t\t\tif req == \"enemy_minion\" or req == \"enemy_minion_hp3\":\n\t\t\t\tvar valid_t: Array[int] = get_valid_target_lanes(ENEMY, req, c.data.type == \"spell\")\n\t\t\t\tif valid_t.is_empty():\n\t\t\t\t\tif c.data.type == \"spell\":\n\t\t\t\t\t\tcontinue\n\t\t\t\telse:\n\t\t\t\t\teff_target = valid_t[0]\n\t\t\telif req == \"friendly_minion\":\n\t\t\t\tvar valid_f: Array[int] = get_valid_target_lanes(ENEMY, req, true)\n\t\t\t\tif valid_f.is_empty():\n\t\t\t\t\tcontinue\n\t\t\t\teff_target = valid_f[0]\n\n\t\t\t# 选择献祭祭品（优先选择攻击力最低的随从如松鼠、电子羊、骷髅）\n\t\t\tvar sac_lanes: Array[int] = []\n\t\t\tif c.data.sacrifice > 0:\n\t\t\t\tvar valid_s: Array[int] = get_valid_sacrifice_lanes(ENEMY, c.data.sacrifice_cond)\n\t\t\t\tvalid_s.sort_custom(func(la: int, lb: int) -> bool:\n\t\t\t\t\treturn board[ENEMY][la].current_atk < board[ENEMY][lb].current_atk\n\t\t\t\t)\n\t\t\t\tfor i in range(c.data.sacrifice):\n\t\t\t\t\tsac_lanes.append(valid_s[i])\n\n\t\t\t# 选择放置列（优先对位阻挡我方高攻随从或空列）\n\t\t\tvar place_lane: int = find_first_empty_lane(ENEMY)\n\t\t\tif place_lane == -1 and not sac_lanes.is_empty():\n\t\t\t\tplace_lane = sac_lanes[0]\n\t\t\tfor l in range(LANES):\n\t\t\t\tif board[ENEMY][l] == null and board[PLAYER][l] != null:\n\t\t\t\t\tplace_lane = l\n\t\t\t\t\tbreak\n\n\t\t\tvar choice_idx: int = 0\n\t\t\tif c.data.id == \"cmwc3gozg0rat\" and _count_mech_in_hand(ENEMY) >= 3:\n\t\t\t\tchoice_idx = 1\n\t\t\tif play_card_from_hand(ENEMY, c, max(0, place_lane), sac_lanes, eff_target, choice_idx):\n\t\t\t\tacted = true\n\t\t\t\tbreak\n\n\t# 尝试激活场上随从的【启动】能力\n\tfor l in range(LANES):\n\t\tif board[ENEMY][l] != null:\n\t\t\tactivate_minion_ability(ENEMY, l)\n\n\t# 敌方场攻结算：回合内已在各随从入场时立即攻击，此处对在场老随从执行本回合例行战道攻击\n\tfor l in [4, 3, 2, 1, 0]:\n\t\tif is_game_over:\n\t\t\tbreak\n\t\tvar m: CardInstance = board[ENEMY][l]\n\t\tif m != null:\n\t\t\tperform_minion_combat(ENEMY, l)\n\n\tif not is_game_over:\n\t\tend_turn(ENEMY)\n\nfunc _log(msg: String) -> void:\n\tbattle_log_added.emit(msg)\n\n## 按随从最先进入战场的顺序（enter_order 升序）依次分配伤害；随从死亡后剩余伤害继续转移给下一个随从，若 include_leader 为真则溢出伤害打在主战者身上\nfunc distribute_damage(target_side: int, total_dmg: int, include_leader: bool = true, source_minion: CardInstance = null) -> void:\n\tvar rem: int = total_dmg\n\twhile rem > 0 and not is_game_over:\n\t\tvar alive_lanes: Array[int] = []\n\t\tfor l in range(LANES):\n\t\t\tif board[target_side][l] != null:\n\t\t\t\talive_lanes.append(l)\n\t\tif alive_lanes.is_empty():\n\t\t\tif include_leader:\n\t\t\t\tdeal_damage_to_leader(target_side, rem, source_minion)\n\t\t\tbreak\n\t\talive_lanes.sort_custom(func(la: int, lb: int) -> bool:\n\t\t\treturn board[target_side][la].enter_order < board[target_side][lb].enter_order\n\t\t)\n\t\tvar first_lane: int = alive_lanes[0]\n\t\tvar m: CardInstance = board[target_side][first_lane]\n\t\tif m.has_kw(\"屏障\"):\n\t\t\tdeal_damage_to_minion(target_side, first_lane, 1, source_minion)\n\t\t\trem -= 1\n\t\telse:\n\t\t\tvar needed: int = max(1, m.current_hp)\n\t\t\tvar dmg_now: int = min(rem, needed)\n\t\t\tdeal_damage_to_minion(target_side, first_lane, dmg_now, source_minion)\n\t\t\trem -= dmg_now\n", "EffectScriptParser.gd": "class_name EffectScriptParser\nextends RefCounted\n## 影之诗：超凡世界标准规范用语通用效果解析器 (EffectScriptParser)\n## 让用户在「卡牌设计器」中按规范用语编写的任何新卡牌 JSON 无需修改代码即可自动解析并执行效果！\n##\n## 支持的标准规范用语语法（可自由组合多句，以句号「。」或换行分隔）：\n## 1. 抽牌与检索：\n##    - \"抽取X张卡牌\" / \"从牌库抽取X张「种族」随从\"\n## 2. 衍生物与手牌生成：\n##    - \"将X张『卡名』加入手牌\" / \"将X张和本随从同名的随从加入手牌\"\n## 3. 战场召唤、招募与亡者召还：\n##    - \"召唤X个『卡名』到战场上\" / \"召唤1张和本随从同名的卡牌加入战场\"\n##    - \"【招募_能量X】仅限「种族」，发动Y次\"\n##    - \"【亡者召还_能量X】仅限「种族」，发动Y次\"\n## 4. 伤害、破坏、消失、变身与恢复：\n##    - \"选择对手的战场上的1个随从，对其造成X点伤害\"\n##    - \"对对手的战场上的所有随从造成X点伤害\"\n##    - \"对对手的主战者造成X点伤害\"\n##    - \"回复自己的主战者X点生命值\"\n##    - \"选择1个生命值X以下敌方随从，使其消失\"\n##    - \"选择1个敌方随从，使其破坏\"\n## 5. 属性强化与词条赋予：\n##    - \"使其他「种族」随从获得+X/+Y\" / \"选择1个友方随从，使其获得+X/+Y\"\n##    - \"使其获得【守护】\" / \"使场上所有『卡名』获得【守护】\"\n## 6. 资源操作：\n##    - \"骨头+X\" / \"能量+X\" / \"你使用的下一张「种族」随从卡能量-X\"\n\nstatic func parse_clauses(effect_text: String) -> Array[Dictionary]:\n\tvar actions: Array[Dictionary] = []\n\tvar cleaned: String = effect_text.replace(\"\\n\", \"。\").replace(\"；\", \"。\")\n\tvar sentences: PackedStringArray = cleaned.split(\"。\", false)\n\tfor raw_s in sentences:\n\t\tvar s: String = raw_s.strip_edges()\n\t\tif s == \"\":\n\t\t\tcontinue\n\t\t# 骨头+X\n\t\tif s.find(\"骨头+\") != -1:\n\t\t\tvar idx: int = s.find(\"骨头+\") + 3\n\t\t\tvar val: int = max(1, s.substr(idx).to_int())\n\t\t\tactions.append({\"op\": \"add_bones\", \"value\": val})\n\t\t# 抽取X张卡牌\n\t\tif s.find(\"抽取\") != -1 and s.find(\"张\") != -1:\n\t\t\tvar val: int = 1\n\t\t\tfor ch_i in range(s.length()):\n\t\t\t\tif s.substr(ch_i, 1).is_valid_int():\n\t\t\t\t\tval = s.substr(ch_i, 1).to_int()\n\t\t\t\t\tbreak\n\t\t\tactions.append({\"op\": \"draw\", \"count\": val})\n\t\t# 对对手的战场上的所有随从造成X点伤害\n\t\tif (s.find(\"所有随从\") != -1 or s.find(\"随从全体\") != -1) and s.find(\"伤害\") != -1:\n\t\t\tvar dmg: int = _extract_first_int(s, 3)\n\t\t\tactions.append({\"op\": \"aoe_enemy_minions\", \"damage\": dmg})\n\t\t# 选择1个敌方随从造成X点伤害\n\t\telif (s.find(\"1个随从\") != -1 or s.find(\"1个敌方随从\") != -1) and s.find(\"伤害\") != -1:\n\t\t\tvar dmg: int = _extract_first_int(s.substr(s.find(\"造成\")), 3)\n\t\t\tactions.append({\"op\": \"damage_target_minion\", \"damage\": dmg})\n\t\t# 回复自己的主战者X点生命值\n\t\tif s.find(\"回复\") != -1 and s.find(\"主战者\") != -1:\n\t\t\tvar heal: int = _extract_first_int(s, 3)\n\t\t\tactions.append({\"op\": \"heal_leader\", \"amount\": heal})\n\treturn actions\n\nstatic func _extract_first_int(txt: String, default_val: int = 1) -> int:\n\tvar num_str: String = \"\"\n\tfor i in range(txt.length()):\n\t\tvar c: String = txt.substr(i, 1)\n\t\tif c.is_valid_int():\n\t\t\tnum_str += c\n\t\telif num_str != \"\":\n\t\t\tbreak\n\treturn num_str.to_int() if num_str != \"\" else default_val\n", "CardView.gd": "class_name CardView\nextends Control\n## 影之诗风格华丽卡面组件 (CardView)\n## 采用 Godot _draw() 程序化矢量绘制卡框、稀有度宝石、三维费用角标（能量/献祭/骨头）、种族主题插画、词条徽章与攻防数值\n## 支持鼠标悬停放大发光、可打出绿色流光呼吸、选中献祭红框等丰富交互反馈\n\nsignal card_clicked(card_view: CardView)\nsignal card_right_clicked(card_view: CardView)\nsignal card_hovered(card_view: CardView, is_hovering: bool)\n\n## 关联的静态卡牌模板数据\nvar card_data: CardData\n## 关联的运行时实例（若在手牌或战场上则非空）\nvar card_instance: CardInstance\n## 展示模式：\"hand\"（手牌）、\"board\"（战场随从）、\"gallery\"（构筑图鉴）\nvar display_mode: String = \"gallery\"\n## 是否处于可打出高亮状态\nvar is_playable: bool = false\n## 是否被当前选中（出牌选中或献祭选中）\nvar is_selected: bool = false\n## 是否为待选祭品高亮\nvar is_sacrifice_candidate: bool = false\n## 构筑模式下显示的已投入数量角标（0 表示不显示）\nvar deck_count_badge: int = 0\n\nvar _is_hovered: bool = false\nvar _hover_tween: Tween\n\nfunc _init() -> void:\n\tcustom_minimum_size = Vector2(150, 210)\n\tmouse_filter = Control.MOUSE_FILTER_STOP\n\nfunc setup_from_data(data: CardData, mode: String = \"gallery\") -> void:\n\tcard_data = data\n\tcard_instance = null\n\tdisplay_mode = mode\n\t_update_size_for_mode()\n\tqueue_redraw()\n\nfunc setup_from_instance(inst: CardInstance, mode: String = \"hand\") -> void:\n\tcard_instance = inst\n\tcard_data = inst.data if inst != null else null\n\tdisplay_mode = mode\n\t_update_size_for_mode()\n\tqueue_redraw()\n\nfunc _update_size_for_mode() -> void:\n\tmatch display_mode:\n\t\t\"board\":\n\t\t\tcustom_minimum_size = Vector2(136, 168)\n\t\t\"hand\":\n\t\t\tcustom_minimum_size = Vector2(142, 198)\n\t\t_:\n\t\t\tcustom_minimum_size = Vector2(156, 218)\n\tsize = custom_minimum_size\n\tpivot_offset = size * 0.5\n\nfunc _ready() -> void:\n\tmouse_entered.connect(_on_mouse_entered)\n\tmouse_exited.connect(_on_mouse_exited)\n\nfunc _gui_input(event: InputEvent) -> void:\n\tif event is InputEventMouseButton and event.pressed:\n\t\tif event.button_index == MOUSE_BUTTON_LEFT:\n\t\t\tcard_clicked.emit(self)\n\t\telif event.button_index == MOUSE_BUTTON_RIGHT:\n\t\t\tcard_right_clicked.emit(self)\n\nfunc _on_mouse_entered() -> void:\n\t_is_hovered = true\n\tz_index = 20\n\tif _hover_tween and _hover_tween.is_running():\n\t\t_hover_tween.kill()\n\t_hover_tween = create_tween().set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_BACK)\n\tvar target_scale := Vector2(1.14, 1.14) if display_mode == \"hand\" else Vector2(1.06, 1.06)\n\t_hover_tween.tween_property(self, \"scale\", target_scale, 0.14)\n\tcard_hovered.emit(self, true)\n\tqueue_redraw()\n\nfunc _on_mouse_exited() -> void:\n\t_is_hovered = false\n\tz_index = 0\n\tif _hover_tween and _hover_tween.is_running():\n\t\t_hover_tween.kill()\n\t_hover_tween = create_tween().set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_QUAD)\n\t_hover_tween.tween_property(self, \"scale\", Vector2.ONE, 0.12)\n\tcard_hovered.emit(self, false)\n\tqueue_redraw()\n\nfunc _draw() -> void:\n\tif card_data == null:\n\t\treturn\n\tvar rect := Rect2(Vector2.ZERO, size)\n\tvar font: Font = ThemeDB.fallback_font\n\tvar rarity_col: Color = card_data.get_rarity_color()\n\n\t# 1. 绘制外发光（可打出/选中/悬停/献祭候选）\n\tif is_selected:\n\t\t_draw_rounded_box(rect.grow(5.0), Color(1.0, 0.84, 0.25, 0.85), Color.TRANSPARENT, 0.0)\n\telif is_sacrifice_candidate:\n\t\t_draw_rounded_box(rect.grow(4.0), Color(0.95, 0.22, 0.28, 0.85), Color.TRANSPARENT, 0.0)\n\telif is_playable:\n\t\t_draw_rounded_box(rect.grow(3.5), Color(0.22, 0.95, 0.55, 0.72), Color.TRANSPARENT, 0.0)\n\telif _is_hovered:\n\t\t_draw_rounded_box(rect.grow(3.0), Color(0.45, 0.75, 1.0, 0.55), Color.TRANSPARENT, 0.0)\n\n\t# 2. 绘制卡牌底板与金属边框\n\tvar bg_col := Color(0.10, 0.12, 0.18)\n\tif card_data.race == \"机械\":\n\t\tbg_col = Color(0.09, 0.15, 0.24)\n\telif card_data.race == \"亡灵\":\n\t\tbg_col = Color(0.15, 0.10, 0.20)\n\telif card_data.type == \"spell\":\n\t\tbg_col = Color(0.18, 0.11, 0.16)\n\t_draw_rounded_box(rect, bg_col, rarity_col, 2.5)\n\n\t# 3. 绘制卡面中心程序化主题插画区\n\tvar art_h: float = size.y * (0.46 if display_mode != \"board\" else 0.54)\n\tvar art_rect := Rect2(Vector2(8, 28), Vector2(size.x - 16, art_h))\n\t_draw_procedural_art(art_rect)\n\n\t# 4. 绘制顶部名称横幅\n\tvar title_rect := Rect2(Vector2(6, 5), Vector2(size.x - 12, 22))\n\tdraw_rect(title_rect, Color(0.05, 0.06, 0.10, 0.88), true)\n\tdraw_string(font, Vector2(30, 21), card_data.name, HORIZONTAL_ALIGNMENT_LEFT, size.x - 36, 13, Color(0.98, 0.96, 0.90))\n\n\t# 5. 绘制左上角三维费用徽章（能量 / 献祭 / 骨头）\n\tvar eff_energy: int = card_instance.get_effective_energy() if card_instance != null else card_data.energy\n\tvar badge_y: float = 16.0\n\tif eff_energy > 0 or (card_data.sacrifice == 0 and card_data.bones == 0):\n\t\tdraw_circle(Vector2(16, badge_y), 12.0, Color(0.12, 0.56, 0.98))\n\t\tdraw_arc(Vector2(16, badge_y), 12.0, 0, TAU, 24, Color(0.75, 0.92, 1.0), 2.0)\n\t\tdraw_string(font, Vector2(6, badge_y + 5), str(eff_energy), HORIZONTAL_ALIGNMENT_CENTER, 20, 14, Color.WHITE)\n\t\tbadge_y += 24.0\n\tif card_data.sacrifice > 0:\n\t\tdraw_circle(Vector2(16, badge_y), 11.5, Color(0.78, 0.12, 0.18))\n\t\tdraw_arc(Vector2(16, badge_y), 11.5, 0, TAU, 24, Color(1.0, 0.65, 0.65), 1.8)\n\t\tdraw_string(font, Vector2(4, badge_y + 4), \"祭\" + str(card_data.sacrifice), HORIZONTAL_ALIGNMENT_CENTER, 24, 11, Color(1.0, 0.92, 0.92))\n\t\tbadge_y += 23.0\n\tif card_data.bones > 0:\n\t\tdraw_circle(Vector2(16, badge_y), 11.5, Color(0.72, 0.66, 0.52))\n\t\tdraw_arc(Vector2(16, badge_y), 11.5, 0, TAU, 24, Color(0.96, 0.94, 0.86), 1.8)\n\t\tdraw_string(font, Vector2(4, badge_y + 4), \"骨\" + str(card_data.bones), HORIZONTAL_ALIGNMENT_CENTER, 24, 11, Color(0.12, 0.10, 0.08))\n\n\t# 6. 绘制种族与类型飘带\n\tvar type_y: float = art_rect.end.y + 14.0\n\tdraw_rect(Rect2(Vector2(8, art_rect.end.y + 1), Vector2(size.x - 16, 16)), Color(0.06, 0.08, 0.13, 0.92), true)\n\tdraw_string(font, Vector2(10, type_y), card_data.get_type_cn() + \" · \" + card_data.rarity, HORIZONTAL_ALIGNMENT_CENTER, size.x - 20, 11, rarity_col)\n\n\t# 7. 绘制效果描述或战场词条徽章\n\tif display_mode == \"board\" and card_instance != null:\n\t\tvar badges: Array[String] = card_instance.get_badge_list()\n\t\tvar bx: float = 10.0\n\t\tvar by: float = type_y + 16.0\n\t\tfor b_txt in badges:\n\t\t\tvar bw: float = min(size.x - 20.0, float(b_txt.length() * 11 + 10))\n\t\t\tif bx + bw > size.x - 8.0:\n\t\t\t\tbx = 10.0\n\t\t\t\tby += 18.0\n\t\t\tdraw_rect(Rect2(Vector2(bx, by - 12), Vector2(bw, 16)), Color(0.18, 0.26, 0.42, 0.95), true)\n\t\t\tdraw_string(font, Vector2(bx + 4, by), b_txt, HORIZONTAL_ALIGNMENT_LEFT, bw - 4, 10, Color(0.95, 0.92, 0.65))\n\t\t\tbx += bw + 4.0\n\telse:\n\t\tvar desc_rect := Rect2(Vector2(8, type_y + 4), Vector2(size.x - 16, size.y - type_y - 30))\n\t\tdraw_rect(desc_rect, Color(0.05, 0.06, 0.09, 0.85), true)\n\t\tvar desc_str: String = card_data.get_display_text()\n\t\tif card_instance != null and not card_instance.extra_last_words.is_empty():\n\t\t\tdesc_str += \"\\n【附加谢幕曲】\"\n\t\t_draw_wrapped_text(font, desc_str, Rect2(desc_rect.position + Vector2(4, 12), desc_rect.size - Vector2(8, 6)), 10, Color(0.88, 0.90, 0.95))\n\n\t# 8. 如果是随从，绘制左下角攻击力与右下角生命值（含守护盾牌外框）\n\tif card_data.type == \"minion\":\n\t\tvar show_atk: int = card_instance.current_atk if card_instance != null else card_data.atk\n\t\tvar show_hp: int = card_instance.current_hp if card_instance != null else card_data.hp\n\t\tvar has_guard: bool = card_instance.has_kw(\"守护\") if card_instance != null else card_data.has_keyword(\"守护\")\n\t\tif has_guard:\n\t\t\tdraw_rect(rect.grow(-2.0), Color(0.95, 0.82, 0.32, 0.9), false, 3.0)\n\n\t\t# 左下角攻击力剑标\n\t\tvar atk_pos := Vector2(18, size.y - 16)\n\t\tdraw_circle(atk_pos, 14.0, Color(0.16, 0.44, 0.88))\n\t\tdraw_arc(atk_pos, 14.0, 0, TAU, 24, Color(0.65, 0.86, 1.0), 2.0)\n\t\tdraw_string(font, atk_pos + Vector2(-12, 5), str(show_atk), HORIZONTAL_ALIGNMENT_CENTER, 24, 14, Color.WHITE)\n\n\t\t# 右下角生命值血滴标\n\t\tvar hp_pos := Vector2(size.x - 18, size.y - 16)\n\t\tvar hp_col := Color(0.82, 0.18, 0.24)\n\t\tdraw_circle(hp_pos, 14.0, hp_col)\n\t\tdraw_arc(hp_pos, 14.0, 0, TAU, 24, Color(1.0, 0.72, 0.75), 2.0)\n\t\tvar txt_col := Color(0.4, 1.0, 0.5) if (card_instance != null and show_hp > card_data.hp) else Color.WHITE\n\t\tdraw_string(font, hp_pos + Vector2(-12, 5), str(show_hp), HORIZONTAL_ALIGNMENT_CENTER, 24, 14, txt_col)\n\n\t# 9. 构筑模式下若已投入卡组，右上角显示 \"×N\" 徽章\n\tif deck_count_badge > 0:\n\t\tvar badge_rect := Rect2(Vector2(size.x - 36, 4), Vector2(32, 20))\n\t\tdraw_rect(badge_rect, Color(0.92, 0.65, 0.12), true)\n\t\tdraw_string(font, Vector2(size.x - 34, 18), \"x%d\" % deck_count_badge, HORIZONTAL_ALIGNMENT_CENTER, 28, 12, Color(0.08, 0.08, 0.1))\n\n## 根据卡牌种族与属性绘制独特的程序化几何奇幻插画\nfunc _draw_procedural_art(r: Rect2) -> void:\n\tvar c1 := Color(0.14, 0.24, 0.38)\n\tvar c2 := Color(0.28, 0.65, 0.95)\n\tif card_data.race == \"机械\":\n\t\tc1 = Color(0.08, 0.22, 0.34)\n\t\tc2 = Color(0.15, 0.85, 0.96)\n\telif card_data.race == \"亡灵\":\n\t\tc1 = Color(0.16, 0.08, 0.24)\n\t\tc2 = Color(0.68, 0.32, 0.92)\n\telif card_data.type == \"spell\":\n\t\tc1 = Color(0.26, 0.10, 0.18)\n\t\tc2 = Color(0.98, 0.45, 0.25)\n\tdraw_rect(r, c1, true)\n\tvar center: Vector2 = r.get_center()\n\tvar radius: float = min(r.size.x, r.size.y) * 0.34\n\t# 依据卡牌 ID 哈希生成稳定的几何纹章\n\tvar seed_val: int = absi(card_data.id.hash())\n\tvar points_cnt: int = 3 + (seed_val % 5)\n\tdraw_circle(center, radius * 1.05, Color(c2.r, c2.g, c2.b, 0.22))\n\tdraw_arc(center, radius * 0.88, 0, TAU, 32, c2, 2.0)\n\tvar poly: PackedVector2Array = []\n\tfor i in range(points_cnt):\n\t\tvar ang: float = float(i) * TAU / float(points_cnt) - PI * 0.5\n\t\tpoly.append(center + Vector2(cos(ang), sin(ang)) * radius * 0.72)\n\tif poly.size() >= 3:\n\t\tdraw_colored_polygon(poly, Color(c2.r, c2.g, c2.b, 0.45))\n\tdraw_rect(r, card_data.get_rarity_color(), false, 1.2)\n\nfunc _draw_rounded_box(r: Rect2, fill: Color, border: Color, border_w: float) -> void:\n\tdraw_rect(r, fill, true)\n\tif border_w > 0.0:\n\t\tdraw_rect(r, border, false, border_w)\n\nfunc _draw_wrapped_text(font: Font, txt: String, area: Rect2, fsize: int, col: Color) -> void:\n\tvar lines: PackedStringArray = txt.split(\"\\n\")\n\tvar y: float = area.position.y\n\tvar max_chars_per_line: int = max(8, int(area.size.x / (float(fsize) * 0.95)))\n\tfor raw_line in lines:\n\t\tvar pos: int = 0\n\t\twhile pos < raw_line.length():\n\t\t\tif y > area.end.y:\n\t\t\t\treturn\n\t\t\tvar sub: String = raw_line.substr(pos, max_chars_per_line)\n\t\t\tdraw_string(font, Vector2(area.position.x, y), sub, HORIZONTAL_ALIGNMENT_LEFT, area.size.x, fsize, col)\n\t\t\ty += float(fsize) + 3.0\n\t\t\tpos += max_chars_per_line\n", "DeckBuilderView.gd": "class_name DeckBuilderView\nextends Control\n## 卡组构筑界面控制器 (DeckBuilderView)\n## 支持按种族/费用/关键词筛选全部 38 张卡牌、查看卡牌完整大图详情、左键添加/右键移除卡组卡牌、\n## 切换三套预设卡组、一键智能补满 40 张、导入卡牌设计器 v1.9 JSON 数据并持久化保存\n\nsignal back_to_menu_requested()\nsignal start_battle_requested()\n\nvar _filter_race: String = \"全部\"\nvar _include_tokens: bool = false\nvar _search_keyword: String = \"\"\n\nvar _card_grid: GridContainer\nvar _deck_list_vbox: VBoxContainer\nvar _deck_selector: OptionButton\nvar _status_label: Label\nvar _detail_label: RichTextLabel\nvar _file_dialog: FileDialog\nvar _import_text_edit: TextEdit\n\nfunc _ready() -> void:\n\t_build_ui()\n\t_refresh_all()\n\nfunc _build_ui() -> void:\n\t# 背景底色\n\tvar bg := ColorRect.new()\n\tbg.color = Color(0.06, 0.08, 0.13)\n\tbg.set_anchors_preset(Control.PRESET_FULL_RECT)\n\tadd_child(bg)\n\n\tvar root_vbox := VBoxContainer.new()\n\troot_vbox.set_anchors_preset(Control.PRESET_FULL_RECT)\n\troot_vbox.add_theme_constant_override(\"separation\", 10)\n\tadd_child(root_vbox)\n\n\t# 顶部导航与筛选工具栏\n\tvar top_bar := HBoxContainer.new()\n\ttop_bar.custom_minimum_size = Vector2(0, 52)\n\ttop_bar.add_theme_constant_override(\"separation\", 12)\n\troot_vbox.add_child(top_bar)\n\n\tvar btn_back := Button.new()\n\tbtn_back.text = \"◀ 返回主菜单\"\n\tbtn_back.custom_minimum_size = Vector2(130, 40)\n\tbtn_back.pressed.connect(func() -> void:\n\t\tAudioManager.play_sfx(\"click\")\n\t\tDeckManager.save_decks()\n\t\tback_to_menu_requested.emit()\n\t)\n\ttop_bar.add_child(btn_back)\n\n\tvar title_lbl := Label.new()\n\ttitle_lbl.text = \"🛠️ 卡组构筑工坊（左键加入卡组 / 右键移出卡组）\"\n\ttitle_lbl.add_theme_font_size_override(\"font_size\", 18)\n\ttop_bar.add_child(title_lbl)\n\n\t# 种族筛选按钮组\n\tfor r_name in [\"全部\", \"机械\", \"亡灵\", \"法术\"]:\n\t\tvar fb := Button.new()\n\t\tfb.text = r_name\n\t\tfb.custom_minimum_size = Vector2(68, 36)\n\t\tfb.pressed.connect(func() -> void:\n\t\t\tAudioManager.play_sfx(\"click\")\n\t\t\t_filter_race = r_name\n\t\t\t_refresh_card_pool()\n\t\t)\n\t\ttop_bar.add_child(fb)\n\n\tvar token_chk := CheckButton.new()\n\ttoken_chk.text = \"显示衍生物(电子羊/骷髅)\"\n\ttoken_chk.toggled.connect(func(on: bool) -> void:\n\t\t_include_tokens = on\n\t\t_refresh_card_pool()\n\t)\n\ttop_bar.add_child(token_chk)\n\n\tvar search_box := LineEdit.new()\n\tsearch_box.placeholder_text = \"搜索卡名/词条(如 谢幕曲/招募)...\"\n\tsearch_box.custom_minimum_size = Vector2(210, 36)\n\tsearch_box.text_changed.connect(func(new_txt: String) -> void:\n\t\t_search_keyword = new_txt.strip_edges()\n\t\t_refresh_card_pool()\n\t)\n\ttop_bar.add_child(search_box)\n\n\tvar btn_import := Button.new()\n\tbtn_import.text = \"📥 导入设计器JSON\"\n\tbtn_import.pressed.connect(_show_import_dialog)\n\ttop_bar.add_child(btn_import)\n\n\t# 主体左右分栏：左侧卡牌收藏网格 + 中部选中卡牌详情 + 右侧当前卡组列表\n\tvar body_hbox := HBoxContainer.new()\n\tbody_hbox.size_flags_vertical = Control.SIZE_EXPAND_FILL\n\tbody_hbox.add_theme_constant_override(\"separation\", 14)\n\troot_vbox.add_child(body_hbox)\n\n\t# 左侧卡牌池滚动区\n\tvar pool_scroll := ScrollContainer.new()\n\tpool_scroll.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\tpool_scroll.size_flags_stretch_ratio = 2.7\n\tbody_hbox.add_child(pool_scroll)\n\n\t_card_grid = GridContainer.new()\n\t_card_grid.columns = 5\n\t_card_grid.add_theme_constant_override(\"h_separation\", 14)\n\t_card_grid.add_theme_constant_override(\"v_separation\", 14)\n\tpool_scroll.add_child(_card_grid)\n\n\t# 右侧卡组管理面板\n\tvar right_panel := PanelContainer.new()\n\tright_panel.custom_minimum_size = Vector2(440, 0)\n\tbody_hbox.add_child(right_panel)\n\n\tvar right_vbox := VBoxContainer.new()\n\tright_vbox.add_theme_constant_override(\"separation\", 8)\n\tright_panel.add_child(right_vbox)\n\n\t# 预设卡组切换下拉框\n\tvar deck_top := HBoxContainer.new()\n\tright_vbox.add_child(deck_top)\n\t_deck_selector = OptionButton.new()\n\t_deck_selector.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\tfor i in range(DeckManager.decks.size()):\n\t\t_deck_selector.add_item(str(DeckManager.decks[i].get(\"name\", \"卡组 %d\" % (i + 1))), i)\n\t_deck_selector.selected = DeckManager.current_deck_index\n\t_deck_selector.item_selected.connect(func(idx: int) -> void:\n\t\tDeckManager.current_deck_index = idx\n\t\t_refresh_all()\n\t)\n\tdeck_top.add_child(_deck_selector)\n\n\tvar btn_auto := Button.new()\n\tbtn_auto.text = \"✨ 自动补满40张\"\n\tbtn_auto.pressed.connect(func() -> void:\n\t\tAudioManager.play_sfx(\"buff\")\n\t\tDeckManager.auto_complete_deck(DeckManager.get_current_deck())\n\t\tDeckManager.save_decks()\n\t\t_refresh_all()\n\t)\n\tdeck_top.add_child(btn_auto)\n\n\tvar btn_clear := Button.new()\n\tbtn_clear.text = \"🗑️ 清空\"\n\tbtn_clear.pressed.connect(func() -> void:\n\t\tAudioManager.play_sfx(\"click\")\n\t\tDeckManager.get_current_deck()[\"cards\"] = {}\n\t\t_refresh_all()\n\t)\n\tdeck_top.add_child(btn_clear)\n\n\t_status_label = Label.new()\n\t_status_label.add_theme_font_size_override(\"font_size\", 15)\n\tright_vbox.add_child(_status_label)\n\n\tvar deck_scroll := ScrollContainer.new()\n\tdeck_scroll.size_flags_vertical = Control.SIZE_EXPAND_FILL\n\tright_vbox.add_child(deck_scroll)\n\n\t_deck_list_vbox = VBoxContainer.new()\n\t_deck_list_vbox.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\t_deck_list_vbox.add_theme_constant_override(\"separation\", 4)\n\tdeck_scroll.add_child(_deck_list_vbox)\n\n\t# 选中卡牌完整规则详情展示框\n\t_detail_label = RichTextLabel.new()\n\t_detail_label.bbcode_enabled = true\n\t_detail_label.custom_minimum_size = Vector2(0, 150)\n\t_detail_label.text = \"[b]💡 悬停或点击左侧任意卡牌查看完整词条与设计师备注[/b]\"\n\tright_vbox.add_child(_detail_label)\n\n\tvar btn_battle := Button.new()\n\tbtn_battle.text = \"⚔️ 使用当前卡组开始对战\"\n\tbtn_battle.custom_minimum_size = Vector2(0, 46)\n\tbtn_battle.pressed.connect(func() -> void:\n\t\tvar check: Dictionary = DeckManager.validate_deck(DeckManager.get_current_deck())\n\t\tif not bool(check.get(\"valid\", false)):\n\t\t\tDeckManager.auto_complete_deck(DeckManager.get_current_deck())\n\t\tDeckManager.save_decks()\n\t\tAudioManager.play_sfx(\"turn\")\n\t\tstart_battle_requested.emit()\n\t)\n\tright_vbox.add_child(btn_battle)\n\n\t# 初始化本地文件选择弹窗（支持直接选择电脑中的 .json 卡牌设计器导出文件）\n\t_file_dialog = FileDialog.new()\n\t_file_dialog.file_mode = FileDialog.FILE_MODE_OPEN_FILE\n\t_file_dialog.access = FileDialog.ACCESS_FILESYSTEM\n\t_file_dialog.filters = PackedStringArray([\"*.json ; 卡牌设计器 JSON 文件\"])\n\t_file_dialog.title = \"选择电脑中的「卡牌构筑对战 · 卡牌设计器」JSON 文件\"\n\t_file_dialog.min_size = Vector2(720, 480)\n\t_file_dialog.file_selected.connect(_on_file_selected)\n\tadd_child(_file_dialog)\n\nfunc _refresh_all() -> void:\n\t_refresh_card_pool()\n\t_refresh_deck_list()\n\nfunc _refresh_card_pool() -> void:\n\tfor child in _card_grid.get_children():\n\t\tchild.queue_free()\n\tvar cur_deck: Dictionary = DeckManager.get_current_deck()\n\tvar cards_map: Dictionary = cur_deck.get(\"cards\", {})\n\tfor c in CardDatabase.all_cards:\n\t\tif not _include_tokens and c.is_token:\n\t\t\tcontinue\n\t\tif _filter_race == \"机械\" and c.race != \"机械\":\n\t\t\tcontinue\n\t\tif _filter_race == \"亡灵\" and c.race != \"亡灵\":\n\t\t\tcontinue\n\t\tif _filter_race == \"法术\" and c.type != \"spell\":\n\t\t\tcontinue\n\t\tif _search_keyword != \"\":\n\t\t\tvar hay: String = c.name + c.race + c.get_display_text() + c.notes\n\t\t\tif hay.find(_search_keyword) == -1:\n\t\t\t\tcontinue\n\n\t\tvar cv := CardView.new()\n\t\tcv.setup_from_data(c, \"gallery\")\n\t\tcv.deck_count_badge = int(cards_map.get(c.id, 0))\n\t\tcv.card_clicked.connect(func(_v: CardView) -> void:\n\t\t\t_add_card_to_current_deck(c)\n\t\t)\n\t\tcv.card_right_clicked.connect(func(_v: CardView) -> void:\n\t\t\t_remove_card_from_current_deck(c.id)\n\t\t)\n\t\tcv.card_hovered.connect(func(_v: CardView, hovering: bool) -> void:\n\t\t\tif hovering:\n\t\t\t\t_show_card_detail(c)\n\t\t)\n\t\t_card_grid.add_child(cv)\n\nfunc _refresh_deck_list() -> void:\n\tfor child in _deck_list_vbox.get_children():\n\t\tchild.queue_free()\n\tvar cur_deck: Dictionary = DeckManager.get_current_deck()\n\tvar cards_map: Dictionary = cur_deck.get(\"cards\", {})\n\tvar check: Dictionary = DeckManager.validate_deck(cur_deck)\n\t_status_label.text = str(check.get(\"reason\", \"\"))\n\t_status_label.modulate = Color(0.35, 1.0, 0.55) if bool(check.get(\"valid\", false)) else Color(1.0, 0.72, 0.35)\n\n\tvar sorted_ids: Array = cards_map.keys()\n\tsorted_ids.sort_custom(func(a: String, b: String) -> bool:\n\t\tvar ca: CardData = CardDatabase.get_card(a)\n\t\tvar cb: CardData = CardDatabase.get_card(b)\n\t\tif ca == null or cb == null:\n\t\t\treturn a < b\n\t\tif ca.energy != cb.energy:\n\t\t\treturn ca.energy < cb.energy\n\t\treturn ca.bones < cb.bones\n\t)\n\n\tfor cid in sorted_ids:\n\t\tvar cnt: int = int(cards_map[cid])\n\t\tif cnt <= 0:\n\t\t\tcontinue\n\t\tvar c: CardData = CardDatabase.get_card(cid)\n\t\tif c == null:\n\t\t\tcontinue\n\t\tvar row := HBoxContainer.new()\n\t\tvar cost_lbl := Label.new()\n\t\tvar cost_parts: PackedStringArray = []\n\t\tif c.energy > 0 or (c.sacrifice == 0 and c.bones == 0):\n\t\t\tcost_parts.append(\"⚡%d\" % c.energy)\n\t\tif c.sacrifice > 0:\n\t\t\tcost_parts.append(\"🩸%d\" % c.sacrifice)\n\t\tif c.bones > 0:\n\t\t\tcost_parts.append(\"🦴%d\" % c.bones)\n\t\tcost_lbl.text = \"[\" + \"/\".join(cost_parts) + \"]\"\n\t\tcost_lbl.custom_minimum_size = Vector2(90, 28)\n\t\trow.add_child(cost_lbl)\n\n\t\tvar name_btn := Button.new()\n\t\tname_btn.text = \"%s  × %d\" % [c.name, cnt]\n\t\tname_btn.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\t\tname_btn.alignment = HORIZONTAL_ALIGNMENT_LEFT\n\t\tname_btn.pressed.connect(func() -> void:\n\t\t\t_show_card_detail(c)\n\t\t\t_remove_card_from_current_deck(c.id)\n\t\t)\n\t\trow.add_child(name_btn)\n\t\t_deck_list_vbox.add_child(row)\n\nfunc _add_card_to_current_deck(c: CardData) -> void:\n\tif c.is_token:\n\t\t_show_card_detail(c)\n\t\treturn\n\tvar cur_deck: Dictionary = DeckManager.get_current_deck()\n\tvar cards_map: Dictionary = cur_deck.get(\"cards\", {})\n\tvar max_copies: int = int(CardDatabase.rules.get(\"copiesPerCard\", 3))\n\tvar max_total: int = int(CardDatabase.rules.get(\"deckSize\", 40))\n\tvar cur_cnt: int = int(cards_map.get(c.id, 0))\n\tif cur_cnt >= max_copies or DeckManager.get_deck_total_count(cur_deck) >= max_total:\n\t\tAudioManager.play_sfx(\"hit\")\n\t\treturn\n\tcards_map[c.id] = cur_cnt + 1\n\tAudioManager.play_sfx(\"click\")\n\tDeckManager.save_decks()\n\t_refresh_all()\n\nfunc _remove_card_from_current_deck(cid: String) -> void:\n\tvar cur_deck: Dictionary = DeckManager.get_current_deck()\n\tvar cards_map: Dictionary = cur_deck.get(\"cards\", {})\n\tif not cards_map.has(cid):\n\t\treturn\n\tvar cur_cnt: int = int(cards_map[cid]) - 1\n\tif cur_cnt <= 0:\n\t\tcards_map.erase(cid)\n\telse:\n\t\tcards_map[cid] = cur_cnt\n\tAudioManager.play_sfx(\"click\")\n\tDeckManager.save_decks()\n\t_refresh_all()\n\nfunc _show_card_detail(c: CardData) -> void:\n\tvar cost_info: String = \"能量:%d | 献祭:%d%s | 骨头:%d\" % [\n\t\tc.energy,\n\t\tc.sacrifice,\n\t\t(\"(%s)\" % c.sacrifice_cond if c.sacrifice_cond != \"\" else \"\"),\n\t\tc.bones\n\t]\n\tvar stat_info: String = (\"攻击:%d / 生命:%d\" % [c.atk, c.hp]) if c.type == \"minion\" else \"法术卡\"\n\tvar note_str: String = (\"\\n[color=#99b8ff]设计备注：%s[/color]\" % c.notes) if c.notes != \"\" else \"\"\n\t_detail_label.text = \"[b]【%s】[/b] (%s · %s)\\n%s  |  %s\\n[color=#ffe89e]%s[/color]%s\" % [\n\t\tc.name,\n\t\tc.get_type_cn(),\n\t\tc.rarity,\n\t\tcost_info,\n\t\tstat_info,\n\t\tc.get_display_text(),\n\t\tnote_str\n\t]\n\nfunc _show_import_dialog() -> void:\n\t_file_dialog.popup_centered()\n\nfunc _on_file_selected(file_path: String) -> void:\n\tif not FileAccess.file_exists(file_path):\n\t\treturn\n\tvar rf := FileAccess.open(file_path, FileAccess.READ)\n\tif rf == null:\n\t\treturn\n\tvar raw: String = rf.get_as_text()\n\trf.close()\n\tif CardDatabase.parse_json_string(raw, true):\n\t\tvar wf := FileAccess.open(\"user://custom_cards.json\", FileAccess.WRITE)\n\t\tif wf != null:\n\t\t\twf.store_string(raw)\n\t\t\twf.close()\n\t\tAudioManager.play_sfx(\"victory\")\n\t\t_refresh_all()\n", "BattleView.gd": "class_name BattleView\nextends Control\n## 影之诗 × 邪恶冥刻风格核心对战界面控制器 (BattleView)\n## 完整实现：\n## 1. 起手 4 张换牌调度弹窗（Mulligan，确保「使命必达小子」起手必在）\n## 2. 5 列战道实时对位展示、点击空位或献祭后放置随从、点击场上随从发动【启动】能力\n## 3. 多阶段流畅出牌交互状态机：选择手牌 -> 选择【抉择】分支 -> 选择【献祭】友方随从 -> 选择【法术/入场曲目标】 -> 选择放置列\n## 4. 实时三维资源仪表盘（能量水晶、骨头计数器、墓地与已破坏谢幕曲计数、连击计数）与飘字打击 Tween 动画\n\nsignal exit_battle_requested()\n\nenum PlayStep {\n\tIDLE,\n\tSELECT_CHOICE,\n\tSELECT_SACRIFICE,\n\tSELECT_EFFECT_TARGET,\n\tSELECT_HAND_TARGET,\n\tSELECT_LANE\n}\n\nvar engine: BattleEngine\nvar _step: PlayStep = PlayStep.IDLE\nvar _pending_card: CardInstance = null\nvar _pending_choice_idx: int = 0\nvar _pending_sac_lanes: Array[int] = []\nvar _pending_effect_target_lane: int = -1\nvar _pending_hand_target_uid: int = -1\n\nvar _enemy_leader_lbl: Label\nvar _player_leader_lbl: Label\nvar _prompt_banner: Label\nvar _enemy_lanes_hbox: HBoxContainer\nvar _player_lanes_hbox: HBoxContainer\nvar _hand_hbox: HBoxContainer\nvar _log_box: RichTextLabel\nvar _card_inspector: RichTextLabel\nvar _choice_overlay: PanelContainer\nvar _choice_vbox: VBoxContainer\nvar _mulligan_overlay: PanelContainer\nvar _mulligan_hbox: HBoxContainer\nvar _mulligan_selected: Array[int] = []\nvar _end_turn_btn: Button\n\nfunc _ready() -> void:\n\tengine = BattleEngine.new()\n\tadd_child(engine)\n\tengine.state_updated.connect(_refresh_ui)\n\tengine.battle_log_added.connect(_on_battle_log)\n\tengine.floating_text_requested.connect(_on_floating_text)\n\tengine.game_over_triggered.connect(_on_game_over)\n\t_build_ui()\n\t_start_new_match()\n\nfunc _start_new_match() -> void:\n\tvar p_deck: Array[String] = DeckManager.expand_deck_to_id_list(DeckManager.get_current_deck())\n\t# 为敌方 AI 随机挑选一套预设主题卡组\n\tvar ai_idx: int = 0 # 敌方AI固定使用全套40张「赛博机械狂潮」机械卡组\n\tvar e_deck: Array[String] = DeckManager.expand_deck_to_id_list(DeckManager.decks[ai_idx])\n\tengine.start_battle(p_deck, e_deck)\n\t_show_mulligan_popup()\n\t_refresh_ui()\n\nfunc _build_ui() -> void:\n\tvar bg := ColorRect.new()\n\tbg.color = Color(0.05, 0.07, 0.12)\n\tbg.set_anchors_preset(Control.PRESET_FULL_RECT)\n\tadd_child(bg)\n\n\tvar main_hbox := HBoxContainer.new()\n\tmain_hbox.set_anchors_preset(Control.PRESET_FULL_RECT)\n\tmain_hbox.add_theme_constant_override(\"separation\", 10)\n\tadd_child(main_hbox)\n\n\t# 左侧战报与卡牌放大检视栏\n\tvar left_panel := PanelContainer.new()\n\tleft_panel.custom_minimum_size = Vector2(310, 0)\n\tmain_hbox.add_child(left_panel)\n\n\tvar left_vbox := VBoxContainer.new()\n\tleft_vbox.add_theme_constant_override(\"separation\", 8)\n\tleft_panel.add_child(left_vbox)\n\n\tvar top_btns := HBoxContainer.new()\n\tleft_vbox.add_child(top_btns)\n\n\tvar btn_exit := Button.new()\n\tbtn_exit.text = \"◀ 撤退返回\"\n\tbtn_exit.pressed.connect(func() -> void:\n\t\tAudioManager.play_sfx(\"click\")\n\t\texit_battle_requested.emit()\n\t)\n\ttop_btns.add_child(btn_exit)\n\n\tvar btn_rematch := Button.new()\n\tbtn_rematch.text = \"🔄 重新开局\"\n\tbtn_rematch.pressed.connect(func() -> void:\n\t\tAudioManager.play_sfx(\"turn\")\n\t\t_log_box.clear()\n\t\t_start_new_match()\n\t)\n\ttop_btns.add_child(btn_rematch)\n\n\t_card_inspector = RichTextLabel.new()\n\t_card_inspector.bbcode_enabled = true\n\t_card_inspector.custom_minimum_size = Vector2(0, 210)\n\t_card_inspector.text = \"[b]🔍 卡牌详情检视[/b]\\n将鼠标悬停在任意手牌或战场随从上查看完整效果。\"\n\tleft_vbox.add_child(_card_inspector)\n\n\tvar log_title := Label.new()\n\tlog_title.text = \"📜 实时战斗结算记录\"\n\tleft_vbox.add_child(log_title)\n\n\t_log_box = RichTextLabel.new()\n\t_log_box.bbcode_enabled = true\n\t_log_box.scroll_following = true\n\t_log_box.size_flags_vertical = Control.SIZE_EXPAND_FILL\n\tleft_vbox.add_child(_log_box)\n\n\t# 右侧主战场区（敌方信息栏 -> 敌方5列战道 -> 交互提示条 -> 我方5列战道 -> 我方资源与手牌栏）\n\tvar center_vbox := VBoxContainer.new()\n\tcenter_vbox.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\tcenter_vbox.add_theme_constant_override(\"separation\", 8)\n\tmain_hbox.add_child(center_vbox)\n\n\t# 敌方主战者状态栏\n\tvar enemy_bar := PanelContainer.new()\n\tenemy_bar.custom_minimum_size = Vector2(0, 44)\n\tcenter_vbox.add_child(enemy_bar)\n\t_enemy_leader_lbl = Label.new()\n\t_enemy_leader_lbl.add_theme_font_size_override(\"font_size\", 16)\n\tenemy_bar.add_child(_enemy_leader_lbl)\n\n\t# 敌方 5 列战道\n\t_enemy_lanes_hbox = HBoxContainer.new()\n\t_enemy_lanes_hbox.alignment = BoxContainer.ALIGNMENT_CENTER\n\t_enemy_lanes_hbox.add_theme_constant_override(\"separation\", 18)\n\t_enemy_lanes_hbox.custom_minimum_size = Vector2(0, 185)\n\tcenter_vbox.add_child(_enemy_lanes_hbox)\n\n\t# 中央交互操作提示横幅 + 结束回合按钮\n\tvar mid_bar := HBoxContainer.new()\n\tmid_bar.custom_minimum_size = Vector2(0, 42)\n\tcenter_vbox.add_child(mid_bar)\n\n\t_prompt_banner = Label.new()\n\t_prompt_banner.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\t_prompt_banner.add_theme_font_size_override(\"font_size\", 16)\n\t_prompt_banner.modulate = Color(1.0, 0.88, 0.38)\n\tmid_bar.add_child(_prompt_banner)\n\n\tvar btn_cancel := Button.new()\n\tbtn_cancel.text = \"取消选牌 (右键)\"\n\tbtn_cancel.pressed.connect(_cancel_pending_play)\n\tmid_bar.add_child(btn_cancel)\n\n\t_end_turn_btn = Button.new()\n\t_end_turn_btn.text = \"⏳ 结束回合\"\n\t_end_turn_btn.custom_minimum_size = Vector2(150, 40)\n\t_end_turn_btn.pressed.connect(func() -> void:\n\t\tif engine.active_side == BattleEngine.PLAYER and not engine.is_game_over:\n\t\t\t_cancel_pending_play()\n\t\t\tAudioManager.play_sfx(\"turn\")\n\t\t\tengine.end_turn(BattleEngine.PLAYER)\n\t)\n\tmid_bar.add_child(_end_turn_btn)\n\n\t# 我方 5 列战道\n\t_player_lanes_hbox = HBoxContainer.new()\n\t_player_lanes_hbox.alignment = BoxContainer.ALIGNMENT_CENTER\n\t_player_lanes_hbox.add_theme_constant_override(\"separation\", 18)\n\t_player_lanes_hbox.custom_minimum_size = Vector2(0, 185)\n\tcenter_vbox.add_child(_player_lanes_hbox)\n\n\t# 我方主战者三维资源状态栏\n\tvar player_bar := PanelContainer.new()\n\tplayer_bar.custom_minimum_size = Vector2(0, 46)\n\tcenter_vbox.add_child(player_bar)\n\t_player_leader_lbl = Label.new()\n\t_player_leader_lbl.add_theme_font_size_override(\"font_size\", 16)\n\tplayer_bar.add_child(_player_leader_lbl)\n\n\t# 我方底部手牌区\n\tvar hand_scroll := ScrollContainer.new()\n\thand_scroll.size_flags_vertical = Control.SIZE_EXPAND_FILL\n\tcenter_vbox.add_child(hand_scroll)\n\n\t_hand_hbox = HBoxContainer.new()\n\t_hand_hbox.alignment = BoxContainer.ALIGNMENT_CENTER\n\t_hand_hbox.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\t_hand_hbox.add_theme_constant_override(\"separation\", 10)\n\thand_scroll.add_child(_hand_hbox)\n\n\t# 【抉择】弹窗浮层\n\t_choice_overlay = PanelContainer.new()\n\t_choice_overlay.visible = false\n\t_choice_overlay.custom_minimum_size = Vector2(520, 220)\n\t_choice_overlay.position = Vector2(540, 300)\n\tadd_child(_choice_overlay)\n\t_choice_vbox = VBoxContainer.new()\n\t_choice_vbox.add_theme_constant_override(\"separation\", 12)\n\t_choice_overlay.add_child(_choice_vbox)\n\n\t# 起手 4 张换牌调度弹窗浮层\n\t_mulligan_overlay = PanelContainer.new()\n\t_mulligan_overlay.visible = false\n\t_mulligan_overlay.custom_minimum_size = Vector2(760, 340)\n\t_mulligan_overlay.position = Vector2(420, 240)\n\tadd_child(_mulligan_overlay)\n\tvar mul_vbox := VBoxContainer.new()\n\tmul_vbox.add_theme_constant_override(\"separation\", 14)\n\t_mulligan_overlay.add_child(mul_vbox)\n\tvar mul_title := Label.new()\n\tmul_title.text = \"🎴 起手换牌调度：点击勾选想要替换回牌库的卡牌（【使命必达小子】必在起手中）\"\n\tmul_title.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER\n\tmul_vbox.add_child(mul_title)\n\t_mulligan_hbox = HBoxContainer.new()\n\t_mulligan_hbox.alignment = BoxContainer.ALIGNMENT_CENTER\n\t_mulligan_hbox.add_theme_constant_override(\"separation\", 16)\n\tmul_vbox.add_child(_mulligan_hbox)\n\tvar mul_confirm := Button.new()\n\tmul_confirm.text = \"✅ 确认起手手牌并开始第 1 回合\"\n\tmul_confirm.custom_minimum_size = Vector2(260, 42)\n\tmul_confirm.pressed.connect(_confirm_mulligan)\n\tmul_vbox.add_child(mul_confirm)\n\nfunc _show_mulligan_popup() -> void:\n\t_mulligan_selected.clear()\n\t_mulligan_overlay.visible = true\n\t_rebuild_mulligan_cards()\n\nfunc _rebuild_mulligan_cards() -> void:\n\tfor c in _mulligan_hbox.get_children():\n\t\tc.queue_free()\n\tvar hand: Array = engine.leaders[BattleEngine.PLAYER][\"hand\"]\n\tfor i in range(hand.size()):\n\t\tvar inst: CardInstance = hand[i]\n\t\tvar vbox := VBoxContainer.new()\n\t\tvar cv := CardView.new()\n\t\tcv.setup_from_instance(inst, \"hand\")\n\t\tcv.is_selected = _mulligan_selected.has(i)\n\t\tvar idx: int = i\n\t\tcv.card_clicked.connect(func(_v: CardView) -> void:\n\t\t\tif _mulligan_selected.has(idx):\n\t\t\t\t_mulligan_selected.erase(idx)\n\t\t\telse:\n\t\t\t\t_mulligan_selected.append(idx)\n\t\t\tAudioManager.play_sfx(\"click\")\n\t\t\t_rebuild_mulligan_cards()\n\t\t)\n\t\tvbox.add_child(cv)\n\t\tvar tag := Label.new()\n\t\ttag.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER\n\t\ttag.text = \"🔄 替换此牌\" if _mulligan_selected.has(i) else \"✔️ 保留\"\n\t\tvbox.add_child(tag)\n\t\t_mulligan_hbox.add_child(vbox)\n\nfunc _confirm_mulligan() -> void:\n\t_mulligan_overlay.visible = false\n\tengine.perform_mulligan(BattleEngine.PLAYER, _mulligan_selected)\n\tengine.begin_turn(BattleEngine.PLAYER)\n\nfunc _refresh_ui() -> void:\n\tvar pst: Dictionary = engine.leaders[BattleEngine.PLAYER]\n\tvar est: Dictionary = engine.leaders[BattleEngine.ENEMY]\n\n\t_enemy_leader_lbl.text = \"👹 敌方主战者  ❤️ 生命: %d/%d  |  ⚡ 能量: %d/%d  |  🦴 骨头: %d  |  🃏 手牌: %d  |  牌库: %d  |  墓地: %d\" % [\n\t\tint(est[\"hp\"]), int(est[\"max_hp\"]),\n\t\tint(est[\"energy\"]), int(est[\"max_energy\"]),\n\t\tint(est[\"bones\"]),\n\t\test[\"hand\"].size(), est[\"deck\"].size(), est[\"graveyard\"].size()\n\t]\n\t_player_leader_lbl.text = \"🛡️ 我方主战者  ❤️ 生命: %d/%d  |  ⚡ 能量: %d/%d  |  🦴 骨头: %d  |  🔥 本回合连击: %d  |  ⚰️ 已破坏谢幕曲: %d  |  牌库: %d\" % [\n\t\tint(pst[\"hp\"]), int(pst[\"max_hp\"]),\n\t\tint(pst[\"energy\"]), int(pst[\"max_energy\"]),\n\t\tint(pst[\"bones\"]),\n\t\tint(pst[\"cards_played_this_turn\"]),\n\t\tint(pst[\"destroyed_last_words_count\"]),\n\t\tpst[\"deck\"].size()\n\t]\n\n\t_update_prompt_banner()\n\t_rebuild_lanes()\n\t_rebuild_hand()\n\nfunc _update_prompt_banner() -> void:\n\tif engine.is_game_over:\n\t\treturn\n\tmatch _step:\n\t\tPlayStep.IDLE:\n\t\t\t_prompt_banner.text = \"💡 你的回合：点击下方绿色发光手牌出牌（随从放置后将立即对前方发起攻击），或点击场上【赛博牧羊人】发动【启动】能力。\"\n\t\tPlayStep.SELECT_CHOICE:\n\t\t\t_prompt_banner.text = \"⚖️ 请在弹窗中选择【%s】的【抉择】发动分支...\" % _pending_card.data.name\n\t\tPlayStep.SELECT_SACRIFICE:\n\t\t\tvar need: int = _pending_card.data.sacrifice\n\t\t\tvar cond: String = _pending_card.data.sacrifice_cond\n\t\t\t_prompt_banner.text = \"🩸 献祭阶段：请点击我方战场上 %d 个%s随从作为祭品（已选 %d/%d）\" % [\n\t\t\t\tneed, (\"「%s」\" % cond if cond != \"\" else \"\"), _pending_sac_lanes.size(), need\n\t\t\t]\n\t\tPlayStep.SELECT_EFFECT_TARGET:\n\t\t\t_prompt_banner.text = \"🎯 目标指定：请点击战场上高亮的目标随从以结算【%s】的效果\" % _pending_card.data.name\n\t\tPlayStep.SELECT_HAND_TARGET:\n\t\t\t_prompt_banner.text = \"🃏 手牌选择：请点击下方 1 张其他手牌洗回牌库（【%s】入场曲）\" % _pending_card.data.name\n\t\tPlayStep.SELECT_LANE:\n\t\t\t_prompt_banner.text = \"📍 战道部署：请点击我方 5 列战道中的任意空位（或刚才选定的祭品位置）放置【%s】\" % _pending_card.data.name\n\nfunc _rebuild_lanes() -> void:\n\tfor c in _enemy_lanes_hbox.get_children():\n\t\tc.queue_free()\n\tfor c in _player_lanes_hbox.get_children():\n\t\tc.queue_free()\n\n\tfor lane in range(BattleEngine.LANES):\n\t\t_enemy_lanes_hbox.add_child(_create_lane_slot(BattleEngine.ENEMY, lane))\n\t\t_player_lanes_hbox.add_child(_create_lane_slot(BattleEngine.PLAYER, lane))\n\nfunc _create_lane_slot(side: int, lane: int) -> Control:\n\tvar slot := PanelContainer.new()\n\tslot.custom_minimum_size = Vector2(150, 178)\n\tvar m: CardInstance = engine.board[side][lane]\n\tif m != null:\n\t\tvar cv := CardView.new()\n\t\tcv.setup_from_instance(m, \"board\")\n\t\tif side == BattleEngine.PLAYER and _step == PlayStep.SELECT_SACRIFICE:\n\t\t\tvar valid_s: Array[int] = engine.get_valid_sacrifice_lanes(BattleEngine.PLAYER, _pending_card.data.sacrifice_cond)\n\t\t\tcv.is_sacrifice_candidate = valid_s.has(lane)\n\t\t\tcv.is_selected = _pending_sac_lanes.has(lane)\n\t\tcv.card_clicked.connect(func(_v: CardView) -> void:\n\t\t\t_on_lane_clicked(side, lane)\n\t\t)\n\t\tcv.card_hovered.connect(func(_v: CardView, hov: bool) -> void:\n\t\t\tif hov:\n\t\t\t\t_inspect_instance(m)\n\t\t)\n\t\tslot.add_child(cv)\n\telse:\n\t\tvar empty_btn := Button.new()\n\t\tempty_btn.text = \"%s战道 %d\\n[空位]\" % [\"敌方\" if side == BattleEngine.ENEMY else \"我方\", lane + 1]\n\t\tempty_btn.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\t\tempty_btn.size_flags_vertical = Control.SIZE_EXPAND_FILL\n\t\tempty_btn.pressed.connect(func() -> void:\n\t\t\t_on_lane_clicked(side, lane)\n\t\t)\n\t\tslot.add_child(empty_btn)\n\treturn slot\n\nfunc _rebuild_hand() -> void:\n\tfor c in _hand_hbox.get_children():\n\t\tc.queue_free()\n\tvar hand: Array = engine.leaders[BattleEngine.PLAYER][\"hand\"]\n\tfor inst in hand:\n\t\tvar cv := CardView.new()\n\t\tcv.setup_from_instance(inst, \"hand\")\n\t\tvar check: Dictionary = engine.can_play_card(BattleEngine.PLAYER, inst)\n\t\tcv.is_playable = (engine.active_side == BattleEngine.PLAYER and bool(check.get(\"ok\", false)))\n\t\tcv.is_selected = (_pending_card == inst)\n\t\tcv.card_clicked.connect(func(_v: CardView) -> void:\n\t\t\t_on_hand_card_clicked(inst)\n\t\t)\n\t\tcv.card_right_clicked.connect(func(_v: CardView) -> void:\n\t\t\t_cancel_pending_play()\n\t\t)\n\t\tcv.card_hovered.connect(func(_v: CardView, hov: bool) -> void:\n\t\t\tif hov:\n\t\t\t\t_inspect_instance(inst)\n\t\t)\n\t\t_hand_hbox.add_child(cv)\n\n## 点击手牌时的多阶段状态流转\nfunc _on_hand_card_clicked(inst: CardInstance) -> void:\n\tif engine.active_side != BattleEngine.PLAYER or engine.is_game_over:\n\t\treturn\n\t# 若当前处于「滑板跃迁手」选择一张其他手牌洗入牌库的步骤\n\tif _step == PlayStep.SELECT_HAND_TARGET and inst != _pending_card:\n\t\t_pending_hand_target_uid = inst.uid\n\t\t_advance_play_pipeline()\n\t\treturn\n\n\tvar check: Dictionary = engine.can_play_card(BattleEngine.PLAYER, inst)\n\tif not bool(check.get(\"ok\", false)):\n\t\t_prompt_banner.text = \"⚠️ 无法打出【%s】：%s\" % [inst.data.name, str(check.get(\"reason\", \"\"))]\n\t\tAudioManager.play_sfx(\"hit\")\n\t\treturn\n\n\t_pending_card = inst\n\t_pending_choice_idx = 0\n\t_pending_sac_lanes.clear()\n\t_pending_effect_target_lane = -1\n\t_pending_hand_target_uid = -1\n\tAudioManager.play_sfx(\"click\")\n\n\t# 检查是否包含【抉择】\n\tvar choices: Array = engine.get_card_choices(inst)\n\tif not choices.is_empty():\n\t\t_step = PlayStep.SELECT_CHOICE\n\t\t_show_choice_popup(inst, choices)\n\t\t_refresh_ui()\n\t\treturn\n\n\t_advance_play_pipeline()\n\nfunc _show_choice_popup(inst: CardInstance, choices: Array) -> void:\n\tfor c in _choice_vbox.get_children():\n\t\tc.queue_free()\n\tvar title := Label.new()\n\ttitle.text = \"⚖️ 请选择【%s】要发动的【抉择】能力：\" % inst.data.name\n\t_choice_vbox.add_child(title)\n\tfor i in range(choices.size()):\n\t\tvar opt: Dictionary = choices[i]\n\t\tvar opt_txt: String = str(opt.get(\"t\", \"\"))\n\t\tif opt_txt == \"\":\n\t\t\tvar reans: Array = opt.get(\"reans\", [])\n\t\t\tif not reans.is_empty():\n\t\t\t\tvar r0: Dictionary = reans[0]\n\t\t\t\topt_txt = \"【%s_能量%d】仅限「%s」%s\" % [\n\t\t\t\t\tstr(r0.get(\"k\", \"\")),\n\t\t\t\t\tint(r0.get(\"costs\", {}).get(\"energy\", 0)),\n\t\t\t\t\tstr(r0.get(\"type\", \"\")),\n\t\t\t\t\tstr(r0.get(\"effect\", \"\"))\n\t\t\t\t]\n\t\tvar b := Button.new()\n\t\tb.text = \"选项 (%d)：%s\" % [i + 1, opt_txt]\n\t\tb.custom_minimum_size = Vector2(460, 44)\n\t\tvar pick_idx: int = i\n\t\tb.pressed.connect(func() -> void:\n\t\t\t_pending_choice_idx = pick_idx\n\t\t\t_choice_overlay.visible = false\n\t\t\tAudioManager.play_sfx(\"click\")\n\t\t\t_advance_play_pipeline()\n\t\t)\n\t\t_choice_vbox.add_child(b)\n\t_choice_overlay.visible = true\n\n## 自动推进出牌流水线：献祭 -> 手牌目标 -> 战场目标 -> 选择战道放置（或法术直接释放）\nfunc _advance_play_pipeline() -> void:\n\tif _pending_card == null:\n\t\treturn\n\n\t# 1. 是否还需要选择献祭随从\n\tif _pending_card.data.sacrifice > _pending_sac_lanes.size():\n\t\t_step = PlayStep.SELECT_SACRIFICE\n\t\t_refresh_ui()\n\t\treturn\n\n\t# 2. 是否需要选择另一张手牌（如「滑板跃迁手」）\n\tvar is_enh: bool = (engine.will_trigger_enhance(BattleEngine.PLAYER, _pending_card) > 0)\n\tvar req: String = engine.get_card_target_requirement(_pending_card, is_enh)\n\tvar hand: Array = engine.leaders[BattleEngine.PLAYER][\"hand\"]\n\tif req == \"hand_card\" and _pending_hand_target_uid == -1 and hand.size() > 1:\n\t\t_step = PlayStep.SELECT_HAND_TARGET\n\t\t_refresh_ui()\n\t\treturn\n\n\t# 3. 是否需要指定战场上的敌方/友方随从目标\n\tif req in [\"enemy_minion\", \"enemy_minion_hp3\", \"friendly_minion\"] and _pending_effect_target_lane == -1:\n\t\tvar valid_lanes: Array[int] = engine.get_valid_target_lanes(BattleEngine.PLAYER, req, _pending_card.data.type == \"spell\")\n\t\tif not valid_lanes.is_empty():\n\t\t\t_step = PlayStep.SELECT_EFFECT_TARGET\n\t\t\t_refresh_ui()\n\t\t\treturn\n\t\telif _pending_card.data.type == \"spell\":\n\t\t\t_prompt_banner.text = \"⚠️ 场上有合法目标时才能使用法术【%s】！\" % _pending_card.data.name\n\t\t\t_cancel_pending_play()\n\t\t\treturn\n\n\t# 4. 若是法术，无需选择放置列，立即结算\n\tif _pending_card.data.type == \"spell\":\n\t\tengine.play_card_from_hand(\n\t\t\tBattleEngine.PLAYER,\n\t\t\t_pending_card,\n\t\t\t0,\n\t\t\t_pending_sac_lanes,\n\t\t\t_pending_effect_target_lane,\n\t\t\t_pending_choice_idx,\n\t\t\t_pending_hand_target_uid\n\t\t)\n\t\t_cancel_pending_play()\n\t\treturn\n\n\t# 5. 若是随从，进入选择我方战道列步骤\n\t_step = PlayStep.SELECT_LANE\n\t_refresh_ui()\n\n## 点击我方或敌方战道列时的响应\nfunc _on_lane_clicked(side: int, lane: int) -> void:\n\tif engine.active_side != BattleEngine.PLAYER or engine.is_game_over:\n\t\treturn\n\n\tmatch _step:\n\t\tPlayStep.IDLE:\n\t\t\t# 空闲状态下点击我方随从可尝试触发其【启动】能力（如「赛博牧羊人」）\n\t\t\tif side == BattleEngine.PLAYER and engine.board[side][lane] != null:\n\t\t\t\tif not engine.activate_minion_ability(BattleEngine.PLAYER, lane):\n\t\t\t\t\t_inspect_instance(engine.board[side][lane])\n\n\t\tPlayStep.SELECT_SACRIFICE:\n\t\t\tif side == BattleEngine.PLAYER and engine.board[side][lane] != null:\n\t\t\t\tvar valid_s: Array[int] = engine.get_valid_sacrifice_lanes(BattleEngine.PLAYER, _pending_card.data.sacrifice_cond)\n\t\t\t\tif valid_s.has(lane):\n\t\t\t\t\tif _pending_sac_lanes.has(lane):\n\t\t\t\t\t\t_pending_sac_lanes.erase(lane)\n\t\t\t\t\telse:\n\t\t\t\t\t\t_pending_sac_lanes.append(lane)\n\t\t\t\t\tAudioManager.play_sfx(\"click\")\n\t\t\t\t\t_advance_play_pipeline()\n\n\t\tPlayStep.SELECT_EFFECT_TARGET:\n\t\t\tvar is_enh: bool = (engine.will_trigger_enhance(BattleEngine.PLAYER, _pending_card) > 0)\n\t\t\tvar req: String = engine.get_card_target_requirement(_pending_card, is_enh)\n\t\t\tvar expected_side: int = BattleEngine.PLAYER if req == \"friendly_minion\" else BattleEngine.ENEMY\n\t\t\tvar valid_t: Array[int] = engine.get_valid_target_lanes(BattleEngine.PLAYER, req, _pending_card.data.type == \"spell\")\n\t\t\tif side == expected_side and valid_t.has(lane):\n\t\t\t\t_pending_effect_target_lane = lane\n\t\t\t\tAudioManager.play_sfx(\"click\")\n\t\t\t\t_advance_play_pipeline()\n\n\t\tPlayStep.SELECT_LANE:\n\t\t\tif side == BattleEngine.PLAYER:\n\t\t\t\tif engine.board[side][lane] == null or _pending_sac_lanes.has(lane):\n\t\t\t\t\tengine.play_card_from_hand(\n\t\t\t\t\t\tBattleEngine.PLAYER,\n\t\t\t\t\t\t_pending_card,\n\t\t\t\t\t\tlane,\n\t\t\t\t\t\t_pending_sac_lanes,\n\t\t\t\t\t\t_pending_effect_target_lane,\n\t\t\t\t\t\t_pending_choice_idx,\n\t\t\t\t\t\t_pending_hand_target_uid\n\t\t\t\t\t)\n\t\t\t\t\t_cancel_pending_play()\n\nfunc _cancel_pending_play() -> void:\n\t_step = PlayStep.IDLE\n\t_pending_card = null\n\t_pending_sac_lanes.clear()\n\t_pending_effect_target_lane = -1\n\t_pending_hand_target_uid = -1\n\t_choice_overlay.visible = false\n\t_refresh_ui()\n\nfunc _inspect_instance(inst: CardInstance) -> void:\n\tif inst == null:\n\t\treturn\n\tvar c: CardData = inst.data\n\tvar badges: String = \"、\".join(inst.get_badge_list())\n\t_card_inspector.text = \"[b]【%s】[/b] (%s)\\n⚡能量:%d | 🩸献祭:%d | 🦴骨头:%d\\n⚔️当前攻击:%d  ❤️当前生命:%d/%d\\n🏷️词条状态:%s\\n[color=#ffe89e]%s[/color]\" % [\n\t\tc.name, c.get_type_cn(),\n\t\tinst.get_effective_energy(), c.sacrifice, c.bones,\n\t\tinst.current_atk, inst.current_hp, inst.max_hp,\n\t\t(badges if badges != \"\" else \"无\"),\n\t\tc.get_display_text()\n\t]\n\nfunc _on_battle_log(msg: String) -> void:\n\t_log_box.append_text(msg + \"\\n\")\n\nfunc _on_floating_text(side: int, lane: int, text: String, col: Color) -> void:\n\tvar floater := Label.new()\n\tfloater.text = text\n\tfloater.add_theme_font_size_override(\"font_size\", 22)\n\tfloater.modulate = col\n\tvar base_x: float = 520.0 + float(max(0, lane)) * 165.0\n\tvar base_y: float = 420.0 if side == BattleEngine.PLAYER else 170.0\n\tfloater.position = Vector2(base_x, base_y)\n\tadd_child(floater)\n\tvar tw: Tween = create_tween().set_parallel(true)\n\ttw.tween_property(floater, \"position:y\", base_y - 48.0, 0.75)\n\ttw.tween_property(floater, \"modulate:a\", 0.0, 0.75)\n\ttw.chain().tween_callback(floater.queue_free)\n\nfunc _on_game_over(winner_side: int, reason: String) -> void:\n\tvar title_str: String = \"🏆 胜利！你击败了对手！\" if winner_side == BattleEngine.PLAYER else \"💀 战败！请调整构筑再战！\"\n\t_prompt_banner.text = \"%s （%s）—— 点击左上角「重新开局」或「撤退返回」\" % [title_str, reason]\n"};

